window.TADABBUR_HAJJ = {"_meta":{"description":"تدبّرٌ مُسنَد لسورة الحجّ (٢٢)، سورةٌ فيها مكّيٌّ ومدنيّ، محورُها هولُ الساعةِ وإثباتُ البعثِ وتعظيمُ شعائرِ الله والحجّ والجهاد؛ فيها براهينُ البعثِ من خلقِ الإنسانِ والأرض، ومناسكُ الحجّ، والأمرُ بالصبرِ والتوكّل. بُدئت بالحمد. كلُّ آيةٍ مغطّاةٍ تحمل وقفةً مُسنَدةً موسومة (ابن كثير/السعدي).","honesty":"لا نُقدّم شيئًا كإعجازٍ مُثبَت؛ المعنى منقولٌ بتصرّفٍ يسير من التفسيرين بإحالةٍ صريحة، ونصُّ الآيةِ لا يُكتَب هاهنا بأيدينا، بل يُنقَل عند القراءةِ من مصحفٍ محقَّقٍ مضبوط، صيانةً له من الخطأ."},"n":22,"name":"الحج","total_ayahs":78,"audio":[11,18,27,32,37,46,54,70,77,78],"passages":[{"title":"هولُ زلزلةِ الساعة","range":[1,4],"theme":"الأمرُ بالتقوى لعظمِ زلزلةِ الساعة، وذمُّ الجدالِ بغيرِ علم","verses":[{"n":1,"reflection":{"text":"«يا أيها الناس اتقوا ربكم إن زلزلة الساعة شيء عظيم»: يا أيها الناسُ اتّقوا ربّكم بامتثالِ أمره واجتنابِ نهيه، فإنّ زلزلةَ الساعةِ التي تضطرب بها الأرضُ أمرٌ عظيمٌ مهول؛ ففي هذا أنّ التقوى هي العدّةُ ليومِ الزلزلةِ العظيم، وأنّ استحضارَ هوله يبعث على التقوى؛ فاتّقِ الله واستحضر هولَ الساعة، فتلك التقوى تنجّيك في ذلك اليومِ العظيم.","source":"تفسير السعدي","grade":"ma'thur"},"names":["اتقوا ربكم","زلزلة الساعة شيء عظيم"],"heart_state":{"text":"التقوى استعدادًا لهولِ زلزلةِ الساعة."},"action":{"text":"اتّقِ الله في سرّك وعلنك بامتثالِ أمره واجتنابِ نهيه، مستحضرًا هولَ زلزلةِ الساعة؛ فالتقوى هي العدّةُ لذلك اليومِ العظيم، ومن استحضر هوله جدَّ في العملِ واستعدَّ له."}},{"n":2,"reflection":{"text":"«يوم ترونها تذهل كل مرضعة عما أرضعت وتضع كل ذات حمل حملها وترى الناس سكارى وما هم بسكارى ولكن عذاب الله شديد»: يوم ترون زلزلةَ الساعةِ تنسى كلُّ مرضعةٍ رضيعها من الهول، وتُسقِط كلُّ حاملٍ حملها، وترى الناسَ كالسكارى من شدّةِ الفزعِ وما هم بسكارى من خمر، ولكنّ عذابَ الله شديدٌ أذهب عقولهم؛ ففي هذا تصويرُ شدّةِ هولِ ذلك اليومِ الذي يُذهِل الأمَّ عن ولدها؛ فاستحضر شدّةَ ذلك اليوم لتستعدَّ له، فهولُه يذهل العقولَ ويسقط الأحمال.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ شدّةِ هولِ يومِ القيامةِ للاستعداد."},"action":{"text":"استحضر شدّةَ هولِ يومِ القيامةِ الذي تذهل فيه المرضعُ عن رضيعها وتضع الحاملُ حملها، ليحملك ذلك على التقوى والاستعداد؛ فمن استعظم هولَ ذلك اليومِ هان عليه ترْكُ الشهواتِ من أجله."}},{"n":3,"reflection":{"text":"«ومن الناس من يجادل في الله بغير علم ويتبع كل شيطان مريد»، ومن الناسِ من يخاصم في الله وصفاتِه وقدرتِه بغيرِ علمٍ ولا برهان، ويتّبع في ذلك كلَّ شيطانٍ متمرّدٍ من الإنسِ والجنّ؛ ففي هذا ذمُّ الجدالِ في الله بلا علم، وأنّ اتّباعَ الشياطينِ يقود إلى الباطل؛ فلا تجادل في دينِ الله بلا علم، ولا تتّبع دعاةَ الضلال، بل الزم العلمَ والبرهانَ فيما تقول.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ الجدالِ بلا علم، وعدمُ اتّباعِ دعاةِ الضلال."},"action":{"text":"لا تخض في مسائلِ الدينِ والاعتقادِ بلا علمٍ ولا برهان، ولا تتّبع دعاةَ الضلالِ ومريدي الشياطين؛ بل الزم العلمَ والدليلَ فيما تقول وتعتقد، فالجدالُ بلا علمٍ بابُ الزيغِ والضلال."}},{"n":4,"reflection":{"text":"«كتب عليه أنه من تولاه فأنه يضله ويهديه إلى عذاب السعير»: قُضِي وقُدِّر على الشيطانِ المريدِ أنّ من اتّبعه وتولّاه فإنه يضلّه عن الحقّ ويقوده إلى عذابِ النار؛ ففي هذا أنّ متابعةَ الشيطانِ عاقبتها الضلالُ والنار، وأنّ من والاه هلك؛ فاحذر موالاةَ الشيطانِ واتّباعه، فإنّ عاقبةَ من تولّاه الضلالُ في الدنيا والسعيرُ في الآخرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من موالاةِ الشيطانِ وعاقبةِ اتّباعه."},"action":{"text":"احذر أن تتّخذ الشيطانَ وليًّا بطاعته واتّباعِ وسوسته، فإنّ من تولّاه أضلّه وقاده إلى النار؛ فعادِ الشيطانَ ولا تُطعه في شيء، فموالاتُه ضلالٌ في الدنيا وعذابٌ في الآخرة."}}]},{"title":"براهينُ البعثِ من الخلقِ والأرض","range":[5,7],"theme":"أطوارُ خلقِ الإنسان، وإحياءُ الأرضِ الهامدة، دليلًا على البعث","verses":[{"n":5,"reflection":{"text":"«يا أيها الناس إن كنتم في ريب من البعث فإنا خلقناكم من تراب ثم من نطفة ثم من علقة ثم من مضغة مخلقة وغير مخلقة لنبين لكم ونقر في الأرحام ما نشاء إلى أجل مسمى ثم نخرجكم طفلا ثم لتبلغوا أشدكم ومنكم من يتوفى ومنكم من يرد إلى أرذل العمر لكيلا يعلم من بعد علم شيئا وترى الأرض هامدة فإذا أنزلنا عليها الماء اهتزت وربت وأنبتت من كل زوج بهيج»: يا أيها الناسُ إن كنتم شاكّين في البعثِ فتأمّلوا خلقكم: خلقنا أصلكم من تراب، ثم من نطفة، ثم علقة، ثم مضغةٍ تامّةٍ وغيرِ تامّة، لنبيّن لكم قدرتنا، ونثبّت في الأرحامِ ما نشاء إلى وقتٍ مقدَّر، ثم نخرجكم أطفالًا، ثم تبلغون قوّتكم، ومنكم من يموت شابًّا ومنكم من يُردّ إلى أرذلِ العمرِ (الهرمِ) فينسى ما علم؛ وترى الأرضَ يابسةً ميتةً فإذا أنزلنا عليها المطرَ تحرّكت وانتفخت وأنبتت من كلِّ صنفٍ بهيجٍ جميل؛ ففي هذا برهانان قاطعان على البعث: أطوارُ خلقِ الإنسان، وإحياءُ الأرضِ بعد موتها، فمن قدر على ذلك قادرٌ على البعث؛ فتأمّل خلقك ونباتَ الأرضِ ليزول ريبك في البعث، فالقادرُ على البدءِ قادرٌ على الإعادة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["إن كنتم في ريب من البعث","اهتزت وربت وأنبتت"],"heart_state":{"text":"التأمّلُ في أطوارِ الخلقِ وإحياءِ الأرضِ لليقينِ بالبعث."},"action":{"text":"تأمّل في أطوارِ خلقك من ترابٍ ثم نطفةٍ ثم علقةٍ حتى صرت بشرًا، وفي إحياءِ الأرضِ الميتةِ بالمطر، ليزول ريبك في البعث؛ فمن قدر على هذا البدءِ العجيبِ قادرٌ على إعادتك، فأيقن بالبعثِ واعمل له."}},{"n":6,"reflection":{"text":"«ذلك بأن الله هو الحق وأنه يحيي الموتى وأنه على كل شيء قدير»: ذلك الخلقُ والإحياءُ دليلٌ على أنّ الله هو الحقُّ الثابتُ الذي لا يزول، وأنه يحيي الموتى للبعث، وأنه على كلِّ شيءٍ قدير؛ ففي هذا أنّ آياتِ الخلقِ تثبت حقّيّةَ الله وقدرتَه على البعث؛ فأيقن بأنّ الله هو الحقُّ القادرُ على كلِّ شيء، فاعبده وحده، وثق بقدرته على إحيائك بعد موتك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الله هو الحق","على كل شيء قدير"],"heart_state":{"text":"اليقينُ بأنّ الله هو الحقُّ القادرُ على الإحياء."},"action":{"text":"أيقن بأنّ الله هو الحقُّ الثابتُ، القادرُ على إحياءِ الموتى وعلى كلِّ شيء؛ فاعبده وحده متيقّنًا بقدرته، واعمل للبعثِ الذي هو حقٌّ، فالذي أحيا الأرضَ الميتةَ يحييك بعد موتك."}},{"n":7,"reflection":{"text":"«وأن الساعة آتية لا ريب فيها وأن الله يبعث من في القبور»، وأنّ القيامةَ آتيةٌ لا شكَّ فيها، وأنّ الله يبعث من في القبورِ أحياءً للحسابِ والجزاء؛ ففي هذا تقريرُ حتميّةِ الساعةِ والبعث، وأنهما حقٌّ لا ريبَ فيه؛ فأيقن بالساعةِ والبعثِ يقينًا لا شكَّ فيه، واعمل لهما، فمن أيقن بهما استعدَّ ولم يغفل.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الساعة آتية لا ريب فيها"],"heart_state":{"text":"اليقينُ بحتميّةِ الساعةِ والبعثِ والعملُ لهما."},"action":{"text":"أيقن بأنّ الساعةَ آتيةٌ لا ريبَ فيها، وأنّ الله يبعث من في القبور؛ واعمل لذلك اليومِ بالإيمانِ والطاعة؛ فمن رسخ يقينه بالبعثِ استعدَّ له ولم يغترّ بالدنيا، فاجعل يقينك بهما باعثًا لعملك."}}]},{"title":"المجادلُ المتكبّرُ وعاقبتُه","range":[8,10],"theme":"جدالُ المتكبّرِ بلا علمٍ لإضلالِ الناس، وعدلُ الله في الجزاء","verses":[{"n":8,"reflection":{"text":"«ومن الناس من يجادل في الله بغير علم ولا هدى ولا كتاب منير»، ومن الناسِ من يخاصم في الله بغيرِ علمٍ يستند إليه، ولا هدًى يتّبعه، ولا كتابٍ منيرٍ يهتدي به؛ ففي هذا ذمُّ الجدالِ في الله المبنيِّ على الجهلِ والهوى، وأنّ الحقَّ يُتلقّى من العلمِ والهدى والكتاب؛ فلا تقل في الله ودينه إلا بعلمٍ من كتابٍ أو سنّة، ولا تجادل بالهوى، فالجدالُ بلا مستندٍ ضلال.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ الجدالِ في الله بلا علمٍ ولا هدًى ولا كتاب."},"action":{"text":"لا تخض في أمرِ الله ودينه إلا بعلمٍ مستندٍ إلى كتابٍ أو سنّةٍ أو هدًى صحيح، ولا تجادل بالهوى والظنّ؛ فالجدالُ بلا علمٍ ولا هدًى ولا كتابٍ منيرٍ من صفاتِ أهلِ الضلالِ والكِبر."}},{"n":9,"reflection":{"text":"«ثاني عطفه ليضل عن سبيل الله له في الدنيا خزي ونذيقه يوم القيامة عذاب الحريق»: لاويًا عنقه كِبرًا وإعراضًا عن الحقّ ليصدَّ غيره عن سبيلِ الله، له في الدنيا ذلٌّ وخزي، ونذيقه يوم القيامةِ عذابَ النارِ المحرقة؛ ففي هذا أنّ الكِبرَ والصدَّ عن سبيلِ الله عاقبتهما الخزيُ في الدارين، وأنّ التكبّرَ عن الحقِّ هلاك؛ فاحذر الكِبرَ والإعراضَ عن الحقِّ وصدَّ الناسِ عنه، فعاقبتُه خزيٌ في الدنيا وعذابٌ في الآخرة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["ثاني عطفه ليضل عن سبيل الله"],"heart_state":{"text":"الحذرُ من الكِبرِ والصدِّ عن سبيلِ الله."},"action":{"text":"احذر الكِبرَ والإعراضَ عن الحقّ، وأشدُّ منه أن تصدَّ غيرك عن سبيلِ الله؛ فعاقبةُ المتكبّرِ الصادِّ خزيٌ في الدنيا وعذابٌ محرقٌ في الآخرة؛ فتواضع للحقِّ واتبعه وادعُ إليه لا عنه."}},{"n":10,"reflection":{"text":"«ذلك بما قدمت يداك وأن الله ليس بظلام للعبيد»: يقال له: ذلك العذابُ بسببِ ما قدّمت يداك من الكفرِ والمعاصي، وأنّ الله ليس بظلّامٍ للعبيدِ فلا يعذّب أحدًا بغيرِ ذنب؛ ففي هذا أنّ الجزاءَ بالعمل، وأنّ الله عدلٌ لا يظلم أحدًا؛ فراقب ما تقدّمه يداك، فالجزاءُ عليه، واعلم أنّ الله عدلٌ لا يظلمك، فلا تلومنّ إلا نفسك على ما جنيت.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["ليس بظلام للعبيد"],"heart_state":{"text":"مراقبةُ العمل، والعلمُ بأنّ الله عدلٌ لا يظلم."},"action":{"text":"راقب ما تقدّمه يداك من عملٍ فالجزاءُ عليه، واعلم أنّ الله عدلٌ لا يظلم أحدًا مثقالَ ذرّة؛ فما يصيبك من جزاءٍ فبما كسبت، فأحسن عملك، ولا تلم إلا نفسك على تقصيرك."}}]},{"title":"عبادةُ الله على حرف","range":[11,13],"theme":"المتذبذبُ في دينه، وعبادةُ ما لا ينفع ولا يضرّ","verses":[{"n":11,"reflection":{"text":"«ومن الناس من يعبد الله على حرف فإن أصابه خير اطمأن به وإن أصابته فتنة انقلب على وجهه خسر الدنيا والآخرة ذلك هو الخسران المبين»، ومن الناسِ من يعبد الله على شكٍّ وتردّدٍ (على طرف)، فإن أصابه رخاءٌ اطمأنّ بدينه، وإن أصابته شدّةٌ أو ابتلاءٌ ارتدّ عن دينه، خسر الدنيا والآخرة، ذلك هو الخسرانُ البيّن؛ ففي هذا ذمُّ التذبذبِ في الدينِ وربطِ العبادةِ بالمصالحِ الدنيوية، وأنّ الثباتَ هو الفوز؛ فاعبد الله ثباتًا في السرّاءِ والضرّاء، ولا تجعل عبادتك رهنًا بما تنال من دنيا، فذلك خسرانٌ مبين.","source":"تفسير السعدي","grade":"ma'thur"},"names":["يعبد الله على حرف","الخسران المبين"],"heart_state":{"text":"الثباتُ في العبادةِ في السرّاءِ والضرّاءِ لا التذبذب."},"action":{"text":"اعبد الله على يقينٍ وثباتٍ في الرخاءِ والشدّة، ولا تجعل دينك رهنًا بما يصيبك من دنيا؛ فمن عبد الله على حرفٍ ينقلب عند الابتلاء خسر الدارين، والثابتُ في دينه هو الفائز."}},{"n":12,"reflection":{"text":"«يدعو من دون الله ما لا يضره وما لا ينفعه ذلك هو الضلال البعيد»: يدعو هذا المنقلبُ من دون الله أصنامًا لا تقدر على ضرّه إن تركها ولا نفعه إن عبدها، ذلك هو الضلالُ البعيدُ عن الحقّ؛ ففي هذا أنّ عبادةَ ما لا ينفع ولا يضرّ غايةُ الضلال، وأنّ العاقلَ لا يدعو عاجزًا؛ فلا تدعُ ولا ترجُ إلا من يملك نفعك وضرّك، وهو الله وحده، فدعاءُ العاجزِ ضلالٌ بعيد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفرادُ الله بالدعاءِ لأنه وحده النافعُ الضارّ."},"action":{"text":"لا تدعُ ولا ترجُ ولا تخف إلا الله الذي يملك نفعك وضرّك، فدعاءُ ما لا ينفع ولا يضرّ ضلالٌ بعيد؛ فأخلص دعاءك لله وحده، ولا تتعلّق بعاجزٍ لا يقدر على شيء."}},{"n":13,"reflection":{"text":"«يدعو لمن ضره أقرب من نفعه لبئس المولى ولبئس العشير»: يدعو معبودًا ضرّه (في الآخرةِ بالعذاب) أقربُ من نفعه المتوهَّم، لبئس هذا المعبودُ وليًّا ولبئس صاحبًا؛ ففي هذا أنّ المعبودَ الباطلَ ضرُّه محقّقٌ ونفعه موهوم، وأنه بئس المولى؛ فاتّخذ الله وحده مولى وقرينًا، فهو نِعم المولى ونِعم النصير، ودع كلَّ معبودٍ ضرُّه أقربُ من نفعه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّخاذُ الله وحده مولى ونصيرًا."},"action":{"text":"اتّخذ الله وحده مولى ونصيرًا وقرينًا في أمرك كلِّه، فهو نِعم المولى ونِعم النصير؛ ودع كلَّ ما سواه ممّا ضرُّه أقربُ من نفعه، فولايةُ الله عزٌّ، وولايةُ غيره خسران."}}]},{"title":"جزاءُ المؤمنين، والنصرُ بيدِ الله","range":[14,16],"theme":"إدخالُ المؤمنين الجنّة، وأنّ النصرَ من الله، وأنّ الآياتِ بيّنات","verses":[{"n":14,"reflection":{"text":"«إن الله يدخل الذين آمنوا وعملوا الصالحات جنات تجري من تحتها الأنهار إن الله يفعل ما يريد»: إنّ الله يدخل الذين جمعوا الإيمانَ والعملَ الصالحَ جناتٍ تجري من تحتها الأنهار، إنّ الله يفعل ما يريد لا معقّب لحكمه؛ ففي هذا بشارةُ أهلِ الإيمانِ والعملِ بالجنّة، وإثباتُ كمالِ مشيئةِ الله؛ فاجمع بين الإيمانِ والعملِ الصالحِ لتدخل الجنّة، واعلم أنّ الله يفعل ما يريد، فارجُ فضله واخشَ عدله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين الإيمانِ والعملِ رجاءَ الجنّة."},"action":{"text":"اجمع بين الإيمانِ الصادقِ والعملِ الصالحِ لتكون من أهلِ الجناتِ التي تجري من تحتها الأنهار؛ واعلم أنّ الله يفعل ما يريد، فارجُ فضله واعمل لرحمته، ولا تتّكل على العملِ وحده."}},{"n":15,"reflection":{"text":"«من كان يظن أن لن ينصره الله في الدنيا والآخرة فليمدد بسبب إلى السماء ثم ليقطع فلينظر هل يذهبن كيده ما يغيظ»: من كان يظنّ أنّ الله لن ينصر نبيَّه ودينَه في الدنيا والآخرة (فليغِظه ذلك)، فليمدد حبلًا إلى سقفِ بيته ثم ليختنق به، فلينظر هل يُذهِب فعلُه هذا ما يغيظه من نصرِ الله؟ لا؛ ففي هذا أنّ نصرَ الله لدينه واقعٌ لا محالة، وأنّ غيظَ الحاسدِ لا يدفعه؛ فلا يغيظنّك نصرُ الله لأوليائه، وثق بأنّ نصره لدينه آتٍ، فاعمل له ولا تغتظ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بنصرِ الله لدينه، ونبذُ الغيظِ العاجز."},"action":{"text":"ثق بأنّ الله ناصرٌ دينَه وأولياءه في الدنيا والآخرة لا محالة، فلا يغيظنّك ذلك إن كنت من المعاندين، ولا ييئسنّك إن كنت من المؤمنين؛ فاعمل لدينِ الله واثقًا بنصره، فالغيظُ لا يردّ قضاءه."}},{"n":16,"reflection":{"text":"«وكذلك أنزلناه آيات بينات وأن الله يهدي من يريد»، وكذلك أنزلنا هذا القرآنَ آياتٍ واضحاتٍ بيّناتٍ في دلالتها، وأنّ الله يهدي من يريد هدايته ممّن طلبها؛ ففي هذا وضوحُ آياتِ القرآن، وأنّ الهدايةَ بيدِ الله يمنحها من أراد؛ فاطلب الهدايةَ من الله، وتدبّر آياتِه البيّنات، فالهدايةُ بيده، ووسيلتُها تدبّرُ كتابه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الهدايةِ من الله وتدبّرُ آياتِه البيّنات."},"action":{"text":"اطلب الهدايةَ من الله فهو الذي يهدي من يريد، وتعرّض لها بتدبّرِ آياتِ القرآنِ البيّناتِ والعملِ بها؛ فمن صدق في طلبِ الهدى هداه الله، ووسيلةُ ذلك الإقبالُ على كتابه."}}]},{"title":"الفصلُ بين الأديان، وسجودُ الكونِ لله","range":[17,18],"theme":"أنّ الله يفصل بين الملل، وأنّ الخلقَ كلَّه يسجد له","verses":[{"n":17,"reflection":{"text":"«إن الذين آمنوا والذين هادوا والصابئين والنصارى والمجوس والذين أشركوا إن الله يفصل بينهم يوم القيامة إن الله على كل شيء شهيد»: إنّ المؤمنين واليهودَ والصابئين والنصارى والمجوسَ والمشركين، إنّ الله يفصل ويحكم بينهم يوم القيامةِ فيميّز المحقَّ من المبطل، إنّ الله على كلِّ شيءٍ شهيدٌ مطّلع؛ ففي هذا أنّ الفصلَ بين الأديانِ إلى الله يوم القيامة، وأنّ الحقَّ واحدٌ سيتبيّن؛ فالزم الحقَّ الواحد (الإسلام)، واعلم أنّ الله شاهدٌ سيفصل بين الخلق، فاستعدَّ لذلك الفصل.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الله على كل شيء شهيد"],"heart_state":{"text":"لزومُ الحقِّ الواحد، والعلمُ بأنّ الله يفصل بين الخلق."},"action":{"text":"الزم دينَ الحقِّ الواحدَ (الإسلام)، واعلم أنّ الله شهيدٌ على الخلقِ سيفصل بينهم يوم القيامةِ فيتبيّن المحقُّ من المبطل؛ فاحرص أن تكون على الحقِّ الذي يرضاه، واستعدَّ ليومِ الفصل."}},{"n":18,"reflection":{"text":"«ألم تر أن الله يسجد له من في السماوات ومن في الأرض والشمس والقمر والنجوم والجبال والشجر والدواب وكثير من الناس وكثير حق عليه العذاب ومن يهن الله فما له من مكرم إن الله يفعل ما يشاء»: ألم تعلم أنّ الله يسجد له طاعةً وخضوعًا من في السماواتِ والأرض، والشمسُ والقمرُ والنجومُ والجبالُ والشجرُ والدوابُّ وكثيرٌ من الناس (المؤمنون)، وكثيرٌ من الناسِ حقّ عليه العذابُ بامتناعه عن السجود، ومن يُهِنه الله بالشقاءِ فلا مكرمَ له، إنّ الله يفعل ما يشاء؛ ففي هذا أنّ الكونَ كلَّه ساجدٌ خاضعٌ لله، فكن من الساجدين الطائعين لتكون مكرَمًا؛ فاسجد لله وأطعه، ولا تكن ممّن أبى فأهانه الله، فالكرامةُ في السجودِ له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["يسجد له من في السماوات ومن في الأرض","من يهن الله فما له من مكرم"],"heart_state":{"text":"أن يكون العبدُ من الساجدين الخاضعين لله."},"action":{"text":"اسجد لله وأخضع له طاعةً وعبادةً، وكن من الكثيرِ الذين يسجدون له مع الكونِ كلِّه، لتكون مكرَمًا عنده؛ فمن أبى السجودَ استكبارًا أهانه الله فلا مكرمَ له، والعزُّ كلُّه في الخضوعِ لله وطاعته."}}]},{"title":"مصيرُ الخصمين: النارُ والجنّة","range":[19,24],"theme":"عذابُ الكفارِ في النار، ونعيمُ المؤمنين في الجنّة، وهدايتُهم للطيّب","verses":[{"n":19,"reflection":{"text":"«هذان خصمان اختصموا في ربهم فالذين كفروا قطعت لهم ثياب من نار يصب من فوق رءوسهم الحميم»: هذان فريقان (المؤمنون والكفار) اختصموا في ربّهم وأيّهم على الحقّ، فالذين كفروا تُقطَّع لهم ثيابٌ من نارٍ تُلبَسها أجسادهم، ويُصبّ فوق رؤوسهم الماءُ الحارُّ المتناهي في الحرارة؛ ففي هذا بيانُ عاقبةِ الكفرِ بالعذابِ المحيط، وأنّ الخصومةَ في الحقِّ تنتهي بفصلِ الله؛ فاحذر أن تكون من الفريقِ الخاسرِ الذي هذا مصيره، والزم فريقَ الحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من مصيرِ الكفرِ ولزومُ فريقِ الحقّ."},"action":{"text":"احذر أن تكون من فريقِ الكفرِ الذي تُقطَّع له ثيابُ النارِ ويُصبّ فوق رؤوسهم الحميم، والزم فريقَ الإيمانِ والحقّ؛ فالخصومةُ في الحقِّ يفصلها الله، والفوزُ لمن كان على الحقِّ لا على الباطل."}},{"n":20,"reflection":{"text":"«يصهر به ما في بطونهم والجلود»: يُذاب بذلك الحميمِ ما في بطونهم من الأمعاءِ والأحشاءِ وتذوب جلودهم؛ ففي هذا تصويرُ شدّةِ عذابِ النار الذي ينفذ إلى الباطنِ والظاهر؛ فاحذر النارَ التي هذا حالُ عذابها، واعمل على النجاةِ منها بالإيمانِ والطاعة، فعذابها بالغُ الشدّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من شدّةِ عذابِ النارِ والعملُ للنجاة."},"action":{"text":"احذر النارَ التي يذوب بحميمها ما في البطونِ والجلود، واعمل على النجاةِ منها بالإيمانِ والطاعةِ وترْكِ المعاصي؛ فمن استحضر شدّةَ عذابها جدَّ في اجتنابِ ما يوردها من الكفرِ والذنوب."}},{"n":21,"reflection":{"text":"«ولهم مقامع من حديد»، ولأهلِ النارِ مطارقُ من حديدٍ تُضرَب بها رؤوسهم كلّما أرادوا الخروج؛ ففي هذا زيادةٌ في تصويرِ عذابهم وإهانتهم، وأنّ العذابَ محيطٌ بهم من كلِّ جهة؛ فاتّقِ الله واعمل لتنجوَ من هذا العذابِ المهين، فالنارُ دارُ هوانٍ وعذابٍ لا يفتر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التقوى للنجاةِ من عذابِ النارِ المهين."},"action":{"text":"اتّقِ الله واعمل صالحًا لتنجوَ من نارٍ لأهلها فيها مقامعُ من حديد؛ فعذابها مهينٌ محيطٌ لا مهربَ منه، فمن عرف ذلك اجتنب أسبابه ولزم طاعةَ الله."}},{"n":22,"reflection":{"text":"«كلما أرادوا أن يخرجوا منها من غم أعيدوا فيها وذوقوا عذاب الحريق»: كلّما حاول أهلُ النارِ الخروجَ منها من شدّةِ الغمِّ رُدُّوا فيها، ويقال لهم: ذوقوا عذابَ النارِ المحرقة؛ ففي هذا دوامُ عذابهم وانقطاعُ رجائهم في الخروج، وأنّ العذابَ لا ينفكّ عنهم؛ فاحذر دارًا لا خروجَ منها ولا راحة، واعمل لدارِ النعيمِ الباقي، فبين المصيرين بونٌ بعيد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من دارٍ لا خروجَ منها، والعملُ للنعيمِ الباقي."},"action":{"text":"احذر أن تكون من أهلِ نارٍ كلّما أرادوا الخروجَ منها أُعيدوا فيها، واعمل لدارِ النعيمِ الباقي بالإيمانِ والطاعة؛ فوازِن بين مصيرِ أهلِ النارِ ونعيمِ أهلِ الجنّةِ لتؤثر الباقيةَ الصالحة."}},{"n":23,"reflection":{"text":"«إن الله يدخل الذين آمنوا وعملوا الصالحات جنات تجري من تحتها الأنهار يحلون فيها من أساور من ذهب ولؤلؤا ولباسهم فيها حرير»: إنّ الله يدخل الذين آمنوا وعملوا الصالحاتِ جناتٍ تجري من تحتها الأنهار، يُزيَّنون فيها بأساورِ الذهبِ واللؤلؤ، ولباسهم فيها الحرير؛ ففي هذا وصفُ نعيمِ المؤمنين مقابلَ عذابِ الكفار، وأنّ الجنّةَ جزاءُ الإيمانِ والعمل؛ فاعمل بالإيمانِ والصالحاتِ لتنال هذا النعيمَ المقيم، فبين جزاءِ الفريقين ما ترى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ بالإيمانِ والصالحاتِ لنيلِ نعيمِ الجنّة."},"action":{"text":"اعمل بالإيمانِ والعملِ الصالحِ لتكون من أهلِ الجناتِ الذين يُحلَّون بالذهبِ واللؤلؤِ ولباسهم الحرير؛ ووازِن بين نعيمهم وعذابِ الكفارِ لتجدَّ في العملِ للجنّةِ الباقية، فالجزاءُ على قدرِ العمل."}},{"n":24,"reflection":{"text":"«وهدوا إلى الطيب من القول وهدوا إلى صراط الحميد»، وهُدِي أهلُ الجنّةِ في الدنيا إلى الطيّبِ من القولِ (كلمةِ التوحيدِ والذكرِ والقولِ الحسن)، وهُدُوا إلى طريقِ الله المحمودِ (دينِه القويم)؛ ففي هذا أنّ من هُدِي للطيّبِ من القولِ وصراطِ الحقِّ في الدنيا فاز بالجنّةِ في الآخرة؛ فاطلب الهدايةَ إلى طيّبِ القولِ وصراطِ الحقّ، والزمهما، فبهما تُنال الجنّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الطيب من القول","صراط الحميد"],"heart_state":{"text":"طلبُ الهدايةِ إلى طيّبِ القولِ وصراطِ الحقّ."},"action":{"text":"اطلب من الله أن يهديك إلى الطيّبِ من القول (التوحيدِ والذكرِ والكلمةِ الحسنة) وإلى صراطِ دينه القويم، والزمهما؛ فمن هُدِي إليهما في الدنيا هُدِي إلى الجنّةِ في الآخرة، فاجعلهما ديدنك."}}]},{"title":"حرمةُ المسجدِ الحرام","range":[25,25],"theme":"الصدُّ عن المسجدِ الحرامِ وإرادةُ الإلحادِ فيه بالظلم","verses":[{"n":25,"reflection":{"text":"«إن الذين كفروا ويصدون عن سبيل الله والمسجد الحرام الذي جعلناه للناس سواء العاكف فيه والباد ومن يرد فيه بإلحاد بظلم نذقه من عذاب أليم»: إنّ الذين كفروا ويصدّون الناسَ عن دينِ الله وعن المسجدِ الحرامِ الذي جعلناه للناسِ جميعًا سواءً المقيمُ فيه والقادمُ إليه، ومن يُرِد فيه ميلًا عن الحقِّ بظلمٍ ومعصيةٍ نذقه من عذابٍ أليم؛ ففي هذا تعظيمُ حرمةِ المسجدِ الحرام، والتحذيرُ من الصدِّ عنه ومن الظلمِ فيه ولو بالهمّ؛ فعظّم حرماتِ الله وشعائرَه، واحذر الظلمَ في الحرمِ أو الصدَّ عن سبيلِ الله، فذلك موجبٌ للعذاب.","source":"تفسير السعدي","grade":"ma'thur"},"names":["المسجد الحرام","من يرد فيه بإلحاد بظلم"],"heart_state":{"text":"تعظيمُ حرمةِ المسجدِ الحرام، والحذرُ من الظلمِ فيه."},"action":{"text":"عظّم حرمةَ المسجدِ الحرامِ وشعائرَ الله، ولا تصدَّ أحدًا عن سبيلِ الله ولا عن بيته، واحذر الظلمَ والمعصيةَ في الحرمِ فإنه يوجب العذابَ الأليم؛ فالحرمُ أمنٌ للناسِ فلا تنتهك حرمته."},"qadiyya":{"title":"قضيّةُ موضعٍ يُؤاخَذ فيه بالإرادة قبل الفعل","question":"قال الله: ﴿وَمَنْ يُرِدْ فِيهِ بِإِلْحَادٍ بِظُلْمٍ نُذِقْهُ مِنْ عَذَابٍ أَلِيمٍ﴾.\n**فالوعيدُ معلَّقٌ على الإرادة، لا على الوقوع.** ولو أُريد الوقوعُ لكان اللفظُ: ومن يفعل فيه.\nفالقضيّة: **ما الذي أفاده تعليقُ العذاب بالإرادة دون العمل؟** ثمّ: أيبقى الأصلُ في سائر البقاع أنّ العبد لا يُؤاخَذ إلّا بعمله؟ ثمّ: ما موقعُ هذا الوعيد ممّن وُصفوا في صدر الآية؟","background":"ولا يظهر أثرُ اللفظ حتّى يُفرَّق بين بابين:\n**الإرادةُ** عزمٌ يقوم بالقلب.\n**والفعلُ** خروجُ ذلك العزم إلى الجوارح.\nوالأصلُ المستقرّ أنّ المؤاخذة تُناط بالثاني، فلا يُعاقَب العبدُ على ما لم يخرج إلى عمل.\nفإذا عُلّق الوعيدُ بالأوّل وحده، عُلم أنّ ثَمّ خصوصيّةً في المحلّ اقتضت ذلك.\nوحالُ المخاطَبين في صدر الآية أنّهم لم يقفوا عند الإرادة، بل كفروا وصدّوا ومنعوا.","what_happened":"بدأ السعديُّ بحال القوم فقال: «يخبر تعالى عن شناعة ما عليه المشركون الكافرون بربهم»، ثمّ عدّ ما جمعوه: «وأنهم جمعوا بين الكفر بالله ورسوله، وبين الصد عن سبيل الله ومنع الناس من الإيمان، والصد أيضا عن المسجد الحرام».\nثمّ نازعهم دعوى الاختصاص بالمسجد: «الذي ليس ملكا لهم ولا لآبائهم، بل الناس فيه سواء، المقيم فيه، والطارئ إليه».\nثمّ ذكر من صدّوه: «بل صدوا عنه أفضل الخلق محمدا وأصحابه».\n⭐ ثمّ ربط آخرَ الآية بحرمة المسجد فقال: «والحال أن هذا المسجد الحرام، من حرمته واحترامه وعظمته»، ثمّ ساق آخرَ الآية مضمَّنًا في سياق كلامه.\n⭐ ثمّ استخرج الحكمَ **مقرونًا بقيده**: «فمجرد إرادة الظلم والإلحاد في الحرم، موجب للعذاب، وإن كان غيره لا يعاقب العبد عليه إلا بعمل الظلم».\nثمّ رتّب عليه: «فكيف بمن أتى فيه أعظم الظلم، من الكفر والشرك، والصد عن سبيله، ومنع من يريده بزيارة»، ثمّ قال: «فما ظنكم أن يفعل الله بهم؟».\n⭐ ثمّ ختم بما تفيده الآية: «وفي هذه الآية الكريمة، وجوب احترام الحرم، وشدة تعظيمه، والتحذير من إرادة المعاصي فيه وفعلها».","the_verdict":"**فالحاصلُ أنّ الحكم مأخوذٌ من لفظ الإرادة وحده.** فليس في الآية زيادةُ لفظٍ يدلّ على تقديم المؤاخذة، وإنّما فيها أنّ المعلَّق عليه إرادةٌ لا وقوع؛ فمن ثَمّ صحّ قولُه «فمجرد إرادة الظلم والإلحاد في الحرم، موجب للعذاب».\n⭐ **وموضعُ الدقّة أنّه قرن الحكم باستثنائه في نفس الجملة**: «وإن كان غيره لا يعاقب العبد عليه إلا بعمل الظلم». فلم يُطلق حتّى قيّد، فبقي الأصلُ العامّ في سائر البقاع على حاله، وصار ما في الحرم خصوصيّةً لموضعٍ لا حكمًا لكلّ موضع.\nوالزيادةُ ها هنا في الإرادة لا فيما سواها. فقد ختم بالتحذير «من إرادة المعاصي فيه وفعلها»، فبقي العملُ داخلًا، وضُمّت إليه الإرادة؛ فليس الحكمُ نقلًا للمؤاخذة من العمل إلى القلب، بل إلحاقًا للقلب بالعمل في هذا المحلّ.\n⭐ وأمّا موقعُ الوعيد من صدر الآية فهو تمامُ الحجّة عليهم. فقولُه «فكيف بمن أتى فيه أعظم الظلم» انتقالٌ من الأدنى إلى الأعلى: إذا كانت الإرادةُ المجرّدة موجبةً، فمن جمع الكفرَ والشركَ والصدَّ والمنعَ أولى. فليست الجملةُ الأخيرة وعيدًا مبتدأً بنفسه، بل هي المقدّمةُ التي بها يُحكم على من وُصفوا في أوّلها.\n⭐ **فمن ها هنا يقع الغلطُ في ثلاثة مواضع:** فمن نقل الحكم إلى كلّ بقعةٍ فقد أسقط القيدَ الذي نصّ عليه الإمام. ومن قرأ آخرَ الآية وعيدًا قائمًا بنفسه فقد أضاع الاحتجاجَ الذي سيقت له. ومن سوّى بين الإرادة وبين الخاطر الذي يمرّ فلا يُعزَم عليه فقد جاوز اللفظ؛ فإنّ المذكور إرادةٌ لا خطور.","for_you":"فأمّا الذي تخرج به فثلاثة:\n**الأوّل: انظر في عزمك لا في فعلك وحده.** فإن كنتَ داخلًا الحرمَ وفي نفسك خصومةٌ عزمتَ فيها على ظلم، أو معاملةٌ نويتَ فيها أكل مالٍ بباطل، فصفِّ نفسك من ذلك؛ فإنّ الموجِبَ ثمّ هو العزمُ نفسه لا تمامُه.\n**والثاني: لا تُقدّم نفسك بحجّة الإقامة.** فقد نصّ الإمامُ على أنّ «الناس فيه سواء، المقيم فيه، والطارئ إليه»؛ فلا تحجز موضعًا، ولا ترَ لك حقًّا في مكانٍ لأنّك أسبقُ إليه سكنًا.\n**والثالث: لا تكن حائلًا بين أحدٍ وبين البيت.** فأفسح لمن يطوف، ولا تقف في مسار الطائفين لتصوير أو حديث، ولا تُضيّق على من جاء من بعيد. وممّا عُدّ عليهم المنعُ، قال: «ومنع من يريده بزيارة»؛ فإن كان المنعُ مذمومًا فالتضييقُ أدنى صوره.","grade":"ma'thur","source":"تفسيرُ السعديّ لحال المشركين ومطلعُه («يخبر تعالى عن شناعة ما عليه المشركون»)، وقولُه في المسجد إنّه ليس ملكًا لهم («الذي ليس ملكا لهم ولا لآبائهم»)، وذكرُه من صدّوه («بل صدوا عنه أفضل الخلق»)، وربطُه آخرَ الآية بحرمة المسجد («والحال أن هذا المسجد الحرام») وقد ضمّن آخرَ الآية سياقَ كلامه بلا أقواس، واستخراجُه الحكمَ بقيده («فمجرد إرادة الظلم والإلحاد في الحرم»)، وترتيبُه عليه («فكيف بمن أتى فيه أعظم الظلم»)، وذكرُه المنعَ («ومنع من يريده بزيارة»)، وختامُه بما تفيده الآية («وفي هذه الآية الكريمة، وجوب احترام الحرم»): كلُّها بنصّها في تفسير السعديّ (٢٢:٢٥).","honesty":"وممّا يجب أن يُقال:\n**تفريقُنا في التمهيد بين الإرادة والفعل، وقولُنا إنّ الأصل تعليقُ المؤاخذة بالفعل، تمهيدٌ منّا**؛ ومعناه عند الإمام في قوله «وإن كان غيره لا يعاقب العبد عليه إلا بعمل الظلم».\n**وأمّا قولُنا إنّ الحكم مأخوذٌ من لفظ الإرادة وحده، فملاحظةٌ منّا على مأخذ الاستنباط**؛ والإمامُ ساق الحكم ولم يذكر مأخذه.\nوأمّا قولُنا إنّ الحكم إلحاقٌ للقلب بالعمل لا نقلٌ عنه، فاستنباطٌ منّا من جمعه بين الإرادة والفعل في التحذير.\nوأمّا تسميتُنا صنيعَه في قوله «فكيف بمن أتى فيه أعظم الظلم» انتقالًا من الأدنى إلى الأعلى، فوصفٌ منّا لطريقته في الاحتجاج.\nوأمّا قولُنا إنّ آخر الآية ليس وعيدًا مبتدأً بنفسه، فاستنباطٌ منّا من ربطه إيّاه بقوله «والحال»؛ ولم يتكلّم الإمامُ في إعراب الجملة.\n**وأمّا تفريقُنا بين الإرادة وبين الخاطر الذي يمرّ فلا يُعزَم عليه، فاستنباطٌ منّا من لفظ الإرادة**، ولم يتعرّض له الإمام.\nوأمّا ما مثّلنا به من الخصومة والمعاملة، وقولُنا إنّ الموجِبَ هو العزمُ نفسه لا تمامُه، فتنزيلٌ منّا على قوله «فمجرد إرادة الظلم والإلحاد في الحرم، موجب للعذاب»؛ ولم يتعرّض الإمامُ لوقت تركِ العزم ولا لأثر الإقلاع عنه.\nوأمّا جعلُنا التضييقَ أدنى صور المنع، وما ذكرناه من حجز المواضع والوقوف حائلًا، فتنزيلٌ منّا على قوله «بل الناس فيه سواء، المقيم فيه، والطارئ إليه» وقوله «ومنع من يريده بزيارة»، والإمامُ لم يرتّب صور المنع؛ **ومن رأى أنّا وسّعنا فليردّه**."}}]},{"title":"تأسيسُ البيتِ والأذانُ بالحجّ","range":[26,29],"theme":"بناءُ إبراهيمَ البيتَ على التوحيد، والنداءُ بالحجّ، ومنافعُه","verses":[{"n":26,"reflection":{"text":"«وإذ بوأنا لإبراهيم مكان البيت أن لا تشرك بي شيئا وطهر بيتي للطائفين والقائمين والركع السجود»، واذكر إذ عيّنّا لإبراهيمَ مكانَ الكعبةِ ليبنيها، وأمرناه ألّا يشرك بي شيئًا، وأن يطهّر بيتي من الأوثانِ والأنجاسِ للطائفين والمصلّين الراكعين الساجدين؛ ففي هذا أنّ أساسَ البيتِ التوحيدُ والتطهيرُ من الشرك، وأنّ العبادةَ فيه لله وحده؛ فطهّر قلبك وعبادتك من الشركِ كما طُهِّر البيت، وأخلص عبادتك لله وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":["أن لا تشرك بي شيئا","طهر بيتي"],"heart_state":{"text":"إخلاصُ العبادةِ لله وتطهيرُها من الشرك."},"action":{"text":"أخلص عبادتك لله وحده ونقِّها من كلِّ شركٍ ورياء، كما أُمِر إبراهيمُ أن يبنيَ البيتَ على التوحيدِ ويطهّره؛ فطهّر قلبك ومسجدك وعبادتك ممّا يشوب الإخلاص، فالتوحيدُ أساسُ كلِّ عبادة."}},{"n":27,"reflection":{"text":"«وأذن في الناس بالحج يأتوك رجالا وعلى كل ضامر يأتين من كل فج عميق»، وناد في الناسِ بالحجِّ يأتوك مشاةً وركبانًا على كلِّ ناقةٍ ضامرةٍ أتعبها السفر، يأتون من كلِّ طريقٍ بعيد؛ ففي هذا استجابةُ الناسِ لنداءِ الحجِّ عبر القرون، وأنّ الله يسوق عباده إلى بيته من كلِّ مكان؛ فاستشعر عظمةَ هذا النداءِ الذي لبّاه الحجيجُ قرونًا، واشتَق إلى بيتِ الله، ولبِّ نداءه بالحجِّ إن استطعت.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاشتياقُ إلى بيتِ الله وتلبيةُ نداءِ الحجّ."},"action":{"text":"استشعر عظمةَ نداءِ إبراهيمَ بالحجِّ الذي يلبّيه الناسُ من كلِّ فجٍّ عميقٍ إلى اليوم، واشتَق إلى بيتِ الله الحرام؛ ولبِّ فريضةَ الحجِّ متى استطعت، فهي رحلةٌ إلى الله يُغفَر فيها الذنب."}},{"n":28,"reflection":{"text":"«ليشهدوا منافع لهم ويذكروا اسم الله في أيام معلومات على ما رزقهم من بهيمة الأنعام فكلوا منها وأطعموا البائس الفقير»: ليحضروا منافعَ دينيّةً ودنيويّةً لهم في الحجّ، ويذكروا اسمَ الله عند نحرِ الهدي في أيامٍ معلوماتٍ (أيامِ النحرِ والتشريق) شكرًا على ما رزقهم من الأنعام، فكلوا من الهديِ وأطعموا الفقيرَ الشديدَ الحاجة؛ ففي هذا أنّ الحجَّ يجمع منافعَ الدينِ والدنيا، وأنّ من مقاصده ذكرَ الله والإحسانَ للفقراء؛ فاجعل عباداتك جامعةً للمنافع، واذكر الله على نعمه، وأطعم الفقراءَ شكرًا لله.","source":"تفسير السعدي","grade":"ma'thur"},"names":["ليشهدوا منافع لهم"],"heart_state":{"text":"جمعُ المنافعِ في العبادة، وذكرُ الله، وإطعامُ الفقير."},"action":{"text":"اجعل عباداتك جامعةً لمنافعِ الدينِ والدنيا كالحجّ، واذكر اسمَ الله على نعمه شاكرًا، وأطعم الفقيرَ البائسَ من رزقك؛ فالجمعُ بين ذكرِ الله والإحسانِ للخلقِ من مقاصدِ العبادة."}},{"n":29,"reflection":{"text":"«ثم ليقضوا تفثهم وليوفوا نذورهم وليطوفوا بالبيت العتيق»: ثم ليُزيلوا أوساخهم ويقصّوا شعرهم ويقضوا مناسكهم، وليوفوا بما نذروا من الطاعات، وليطوفوا بالبيتِ العتيقِ (القديمِ المعتَقِ من الجبابرة)؛ ففي هذا بيانُ بعضِ مناسكِ الحجّ، والأمرُ بالوفاءِ بالنذور، وتعظيمُ الطوافِ بالبيت؛ فأدِّ العباداتِ على وجهها، وأوفِ بنذورك وعهودك مع الله، وعظّم شعائره كالطوافِ ببيته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["البيت العتيق"],"heart_state":{"text":"أداءُ المناسكِ والوفاءُ بالنذورِ وتعظيمُ الشعائر."},"action":{"text":"أدِّ العباداتِ والمناسكَ على الوجهِ الذي شرعه الله، وأوفِ بنذورك وعهودك معه، وعظّم شعائرَه كالطوافِ ببيته العتيق؛ فالوفاءُ بالعهدِ مع الله وتعظيمُ شعائره من صدقِ العبودية."}}]},{"title":"تعظيمُ الحرماتِ والشعائر","range":[30,33],"theme":"أنّ تعظيمَ حرماتِ الله وشعائرِه من تقوى القلوب، واجتنابُ الشركِ والزور","verses":[{"n":30,"reflection":{"text":"«ذلك ومن يعظم حرمات الله فهو خير له عند ربه وأحلت لكم الأنعام إلا ما يتلى عليكم فاجتنبوا الرجس من الأوثان واجتنبوا قول الزور»: ذلك الأمرُ، ومن يعظّم حرماتِ الله (ما أوجب احترامه) فهو خيرٌ له عند ربّه، وأُحِلّت لكم الأنعامُ إلا ما يُتلى تحريمه، فاجتنبوا الرجسَ الذي هو عبادةُ الأوثان، واجتنبوا قولَ الكذبِ والزور؛ ففي هذا أنّ تعظيمَ حرماتِ الله خيرٌ للعبد، وأنّ اجتنابَ الشركِ وقولِ الزورِ من أعظمِ الواجبات؛ فعظّم حرماتِ الله، واجتنب الشركَ وشهادةَ الزورِ والكذب، فبهما تفسد الديانة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["من يعظم حرمات الله","قول الزور"],"heart_state":{"text":"تعظيمُ حرماتِ الله، واجتنابُ الشركِ وقولِ الزور."},"action":{"text":"عظّم حرماتِ الله بامتثالِ أمره واجتنابِ نهيه، فذلك خيرٌ لك عند ربّك؛ واجتنب رجسَ الأوثانِ (الشركَ) وقولَ الزور (الكذبَ وشهادةَ الزور)، فقد قُرِنا في التحريم، وهما من أعظمِ ما يفسد الدين."}},{"n":31,"reflection":{"text":"«حنفاء لله غير مشركين به ومن يشرك بالله فكأنما خر من السماء فتخطفه الطير أو تهوي به الريح في مكان سحيق»: كونوا مائلين إلى الحقِّ مخلصين لله غيرَ مشركين به، ومن يشرك بالله فمثله في هلاكه وتمزّقه كمن سقط من السماءِ فتخطفه الطيرُ وتقطّعه، أو تلقيه الريحُ في مكانٍ بعيدٍ سحيق؛ ففي هذا تصويرٌ بليغٌ لهلاكِ المشركِ وضياعه، وأنّ الشركَ سقوطٌ وتمزّق؛ فالزم التوحيدَ والإخلاصَ لله، واحذر الشركَ فإنه يُهلِك صاحبه ويمزّقه كلَّ ممزَّق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["حنفاء لله غير مشركين به"],"heart_state":{"text":"لزومُ التوحيدِ والإخلاص، والحذرُ من هلاكِ الشرك."},"action":{"text":"كن حنيفًا مخلصًا لله موحّدًا، واحذر الشركَ أشدَّ الحذر، فمثلُ المشركِ في هلاكه كمن هوى من السماءِ فتخطفه الطيرُ أو تلقيه الريحُ في مهوًى سحيق؛ فالتوحيدُ عصمةٌ ورفعة، والشركُ سقوطٌ وضياع."}},{"n":32,"reflection":{"text":"«ذلك ومن يعظم شعائر الله فإنها من تقوى القلوب»: ذلك الأمرُ، ومن يعظّم شعائرَ الله (معالمَ دينه من المناسكِ والهديِ وغيرها) فإنّ تعظيمها صادرٌ عن تقوى القلوب؛ ففي هذا أنّ تعظيمَ الشعائرِ دليلٌ على تقوى القلب، وأنّ التقوى محلُّها القلب؛ فعظّم شعائرَ الله في قلبك قبل جوارحك، فتعظيمُها علامةُ التقوى، والتقوى في القلبِ لا في الظاهرِ وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":["من يعظم شعائر الله فإنها من تقوى القلوب"],"heart_state":{"text":"تعظيمُ شعائرِ الله دليلًا على تقوى القلب."},"action":{"text":"عظّم شعائرَ الله ومعالمَ دينه في قلبك قبل جوارحك، فتعظيمُها ثمرةُ تقوى القلبِ ودليلها؛ فاحرص أن يكون تعظيمك نابعًا من قلبٍ تقيٍّ خاشع، لا مجردَ فعلٍ ظاهر، فالعبرةُ بما في القلب."}},{"n":33,"reflection":{"text":"«لكم فيها منافع إلى أجل مسمى ثم محلها إلى البيت العتيق»: لكم في الهديِ منافعُ (كالركوبِ والدرِّ والنسل) إلى وقتِ نحرها، ثم مكانُ نحرها ينتهي إلى الحرمِ عند البيتِ العتيق؛ ففي هذا بيانُ منافعِ الهديِ قبل نحره، وأنّ الشرعَ يجمع بين المصلحةِ والعبادة؛ فانتفع بما أباح الله من نعمه، واجعل غايتها التقرّبَ إليه، فالدينُ يجمع بين نفعِ الدنيا وعبادةِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين الانتفاعِ المباحِ والتقرّبِ إلى الله."},"action":{"text":"انتفع بما أباح الله لك من نعمه ومنافعها، واجعل غايتها التقرّبَ إلى الله وطاعته؛ فالشرعُ يجمع بين مصلحةِ الدنيا وعبادةِ الله، فلا تفصل بين انتفاعك ودينك، بل اجعل نعمك عونًا على الطاعة."}}]},{"title":"المنسكُ والإخبات، وشعيرةُ الهدي","range":[34,37],"theme":"أنّ لكلِّ أمّةٍ منسكًا، وصفاتُ المخبتين، وأنّ التقوى هي المقصودُ من الهدي","verses":[{"n":34,"reflection":{"text":"«ولكل أمة جعلنا منسكا ليذكروا اسم الله على ما رزقهم من بهيمة الأنعام فإلهكم إله واحد فله أسلموا وبشر المخبتين»، ولكلِّ أمّةٍ من الأممِ الماضيةِ جعلنا عبادةً ونسكًا يذبحون فيه ليذكروا اسمَ الله على ما رزقهم من الأنعام، فمعبودكم إلهٌ واحدٌ فاستسلموا له وحده، وبشّر المخبتين (المتواضعين المطمئنين إلى الله)؛ ففي هذا أنّ العبادةَ لله في كلِّ أمّة، وأنّ التوحيدَ أصلها، وأنّ البشرى للمخبتين؛ فاستسلم لله وحده، وكن من المخبتين المتواضعين المطمئنين إليه، فلهم البشرى.","source":"تفسير السعدي","grade":"ma'thur"},"names":["فإلهكم إله واحد فله أسلموا","المخبتين"],"heart_state":{"text":"الاستسلامُ لله، وطلبُ صفةِ الإخباتِ والتواضع."},"action":{"text":"استسلم لله وحده فهو إلهك الواحد، وكن من المخبتين المتواضعين المطمئنّين إلى ذكره وطاعته؛ فالبشرى للمخبتين، فاطلب هذه الصفةَ بلينِ القلبِ لله والخضوعِ له والطمأنينةِ بذكره."}},{"n":35,"reflection":{"text":"«الذين إذا ذكر الله وجلت قلوبهم والصابرين على ما أصابهم والمقيمي الصلاة ومما رزقناهم ينفقون»: المخبتون هم الذين إذا ذُكِر الله خافت قلوبهم وخشعت، والصابرون على ما أصابهم من البلاء، والمقيمون للصلاةِ في أوقاتها، والمنفقون ممّا رزقهم الله؛ ففي هذا بيانُ صفاتِ المخبتين الأربع: خشيةُ القلبِ عند الذكر، والصبرُ، وإقامةُ الصلاة، والإنفاق؛ فتخلّق بهذه الصفات: وجَلُ القلبِ عند ذكرِ الله، والصبرُ، والصلاةُ، والإنفاق، لتكون من المخبتين المبشَّرين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["إذا ذكر الله وجلت قلوبهم"],"heart_state":{"text":"التخلّقُ بصفاتِ المخبتين: الخشيةُ والصبرُ والصلاةُ والإنفاق."},"action":{"text":"تخلّق بصفاتِ المخبتين: ليجل قلبك ويخشع إذا ذُكِر الله، واصبر على ما يصيبك من البلاء، وأقم الصلاةَ في أوقاتها، وأنفق ممّا رزقك الله؛ فبهذه الصفاتِ تنال بشرى الإخباتِ ومحبّةَ الله."}},{"n":36,"reflection":{"text":"«والبدن جعلناها لكم من شعائر الله لكم فيها خير فاذكروا اسم الله عليها صواف فإذا وجبت جنوبها فكلوا منها وأطعموا القانع والمعتر كذلك سخرناها لكم لعلكم تشكرون»، والإبلُ العظامُ جعلناها لكم من شعائرِ الله، لكم فيها خيرٌ (ثوابٌ ونفع)، فاذكروا اسمَ الله عليها عند نحرها قائمةً مصطفّة، فإذا سقطت على جنوبها بعد النحرِ فكلوا منها وأطعموا الفقيرَ المتعفّفَ والسائل، كذلك سخّرناها لكم لتشكروا الله؛ ففي هذا أنّ الهديَ شعيرةٌ فيها خيرٌ ونفع، وأنّ ذكرَ الله عند الذبحِ والإطعامَ من مقاصدها؛ فاذكر اسمَ الله عند ذبحك، وأطعم الفقراء، واشكر الله على تسخيرِ نعمه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["من شعائر الله","لعلكم تشكرون"],"heart_state":{"text":"ذكرُ الله عند الذبحِ، والإطعامُ، وشكرُ التسخير."},"action":{"text":"اذكر اسمَ الله عند ذبح نسكك وطعامك، وأطعم منه الفقيرَ المتعفّفَ والسائل، واشكر الله على تسخيرِ الأنعامِ لك؛ فالشعائرُ فيها خيرٌ ونفع، ومقصودها ذكرُ الله والإحسانُ للخلقِ وشكرُ نعمه."}},{"n":37,"reflection":{"text":"«لن ينال الله لحومها ولا دماؤها ولكن يناله التقوى منكم كذلك سخرها لكم لتكبروا الله على ما هداكم وبشر المحسنين»: لن يصل إلى الله لحومُ الهديِ ولا دماؤها، ولكن يصله الإخلاصُ والتقوى منكم، كذلك سخّرها لكم لتعظّموا الله وتكبّروه على ما هداكم إليه من دينه، وبشّر المحسنين في أعمالهم؛ ففي هذا أنّ المقصودَ من العبادةِ التقوى والإخلاصُ لا مجردُ صورتها، وأنّ الأعمالَ بالقلوبِ والنيّات؛ فاحرص على تقوى القلبِ والإخلاصِ في عباداتك، فذلك ما يصعد إلى الله لا مجردُ الصور، وكبّر الله شكرًا على هدايته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["يناله التقوى منكم","لتكبروا الله على ما هداكم"],"heart_state":{"text":"الإخلاصُ والتقوى روحُ العبادةِ لا مجردُ صورتها."},"action":{"text":"احرص على تقوى القلبِ والإخلاصِ في عباداتك، فذلك ما يصل إلى الله ويُقبَل، لا مجردُ صورةِ العملِ ولحمِه ودمِه؛ فأصلح باطنك ونيّتك، وكبّر الله شاكرًا على هدايته، فالعبرةُ بما في القلبِ من التقوى."}}]},{"title":"الإذنُ بالقتالِ ونصرُ الله","range":[38,41],"theme":"دفاعُ الله عن المؤمنين، والإذنُ بالجهادِ دفعًا للظلم، وصفاتُ الممكَّنين","verses":[{"n":38,"reflection":{"text":"«إن الله يدافع عن الذين آمنوا إن الله لا يحب كل خوان كفور»: إنّ الله يدفع عن المؤمنين شرَّ أعدائهم وكيدهم، إنّ الله لا يحبّ كلَّ خائنٍ لأمانته كفورٍ لنعمته؛ ففي هذا بشارةُ المؤمنين بدفاعِ الله عنهم، وأنّ الأمانةَ والشكرَ محبوبان لله؛ فاطمئن إلى أنّ الله يدافع عنك ما دمت مؤمنًا، والزم الأمانةَ والشكرَ لتكون من أهلِ محبّته ودفاعه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["إن الله يدافع عن الذين آمنوا"],"heart_state":{"text":"الاطمئنانُ إلى دفاعِ الله، ولزومُ الأمانةِ والشكر."},"action":{"text":"اطمئن إلى أنّ الله يدافع عن المؤمنين ويدفع عنهم كيدَ أعدائهم، والزم الأمانةَ في حقوقِ الله والخلق، والشكرَ لنعمه؛ فمن كان أمينًا شكورًا مؤمنًا كان في حفظِ الله ودفاعه، فأخلص له."}},{"n":39,"reflection":{"text":"«أذن للذين يقاتلون بأنهم ظلموا وإن الله على نصرهم لقدير»: أُذِن للمؤمنين الذين يقاتلهم الكفارُ أن يقاتلوا بسببِ ما وقع عليهم من الظلم، وإنّ الله على نصرهم لقادر؛ ففي هذا مشروعيةُ الجهادِ دفعًا للظلم، وأنّ النصرَ بيدِ الله؛ فادفع الظلمَ عن نفسك وعن المستضعفين بما شرع الله، وثق بأنّ الله قادرٌ على نصرِ أهلِ الحقّ، فالنصرُ منه لا من كثرةٍ ولا عدّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["إن الله على نصرهم لقدير"],"heart_state":{"text":"دفعُ الظلمِ بما شُرِع، والثقةُ بقدرةِ الله على النصر."},"action":{"text":"ادفع الظلمَ عن نفسك وعن المظلومين بالوسائلِ المشروعة، وثق بأنّ الله قادرٌ على نصرِ أهلِ الحقّ؛ فالجهادُ شُرِع دفعًا للظلمِ لا عدوانًا، والنصرُ من عند الله لمن التزم الحقَّ وتوكّل عليه."}},{"n":40,"reflection":{"text":"«الذين أخرجوا من ديارهم بغير حق إلا أن يقولوا ربنا الله ولولا دفع الله الناس بعضهم ببعض لهدمت صوامع وبيع وصلوات ومساجد يذكر فيها اسم الله كثيرا ولينصرن الله من ينصره إن الله لقوي عزيز»: هم الذين أُخرِجوا من ديارهم ظلمًا لا لذنبٍ إلا لقولهم ربّنا الله، ولولا أن يدفع الله الناسَ بعضهم ببعضٍ (بالجهادِ ونصرةِ الحقّ) لهُدِّمت أماكنُ العبادةِ التي يُذكَر فيها اسمُ الله كثيرًا، ولينصرنّ الله من ينصر دينه، إنّ الله لقويٌّ عزيز؛ ففي هذا أنّ دفعَ الظلمِ يحفظ الدينَ وشعائره، وأنّ الله ينصر من ينصر دينه؛ فانصر دينَ الله ينصرك، واعلم أنّ في دفعِ الباطلِ حفظًا للحقِّ وأهله.","source":"تفسير السعدي","grade":"ma'thur"},"names":["ولينصرن الله من ينصره","قوي عزيز"],"heart_state":{"text":"نصرةُ دينِ الله رجاءَ نصره، وحفظُ شعائره."},"action":{"text":"انصر دينَ الله بما تقدر عليه من قولٍ وعملٍ ودفعٍ للباطل، وثق بوعده «ولينصرن الله من ينصره»؛ فبنصرةِ الحقِّ تُحفَظ شعائرُ الله ومساجده، ومن نصر دينَ الله القويِّ العزيزِ نصره الله وأعزّه."},"qadiyya":{"title":"قضيّةُ ما يُحفظ بالدفع: آيةٌ تذكر الأديرةَ والكنائسَ قبل المساجد","question":"يُقال كثيرًا إنّ القتال في الإسلام إنّما شُرع **لحمل الناس على الدين**. وفي سورة الحجّ آيةٌ تذكر علّةَ الإذن بالقتال، **ثمّ تعدّد ما كان سيُهدم لولا هذا الدفع**، فتذكر أربعةً:\n«**لهُدِّمت صوامعُ وبِيَعٌ وصلواتٌ ومساجد**».\n**والصوامعُ للرهبان، والبِيَعُ للنصارى، والصلواتُ معابدُ اليهود، والمساجدُ للمسلمين.**\n**فانظر الترتيب: ثلاثةٌ من معابد غير المسلمين قبل مساجدنا.**\nفالسؤال: **ما علّةُ الإذن بالقتال في هذه الآية بلفظها؟ ولماذا ذُكرت هذه المعابدُ في هذا المقام؟**","background":"ولا يُفهم موضعُ الآية حتى نعرف حالَها من الصفر:\n**هذه الآيةُ في سياق أوّلِ إذنٍ بالقتال.** فقد مكث المسلمون بمكّة ثلاثةَ عشرَ عامًا يُؤذَون ولا يُؤذن لهم في دفعٍ، ثمّ نزل الإذنُ في هذه السورة: ﴿أُذن للذين يُقاتَلون بأنّهم ظُلموا﴾.\n**فالآيةُ التي نحن فيها تصف من أُذن لهم**: ﴿الذين أُخرجوا من ديارهم بغير حقّ إلّا أن يقولوا ربّنا الله﴾.\n**و«الصوامع»** جمعُ صومعة، وهي معبدُ الراهب المنفرد. **و«البِيَع»** جمعُ بِيعة، وهي كنيسةُ النصارى. **و«الصلوات»** أُريد بها معابدُ اليهود. **و«المساجد»** معروفة.","what_happened":"**أمّا سببُ الإخراج فقد حرّرته الآيةُ نفسُها بأسلوبٍ عجيب.** قالت: أُخرجوا «بغير حقّ **إلّا** أن يقولوا ربّنا الله». **فجعلت توحيدَهم في صورة الذنب استهزاءً بحجّة خصومهم.**\nقال السعديّ: «**إلّا أنّهم وحّدوا الله، وعبدوه مخلصين له الدين، فإن كان هذا ذنبًا، فهو ذنبُهم**». **ونظّرها بقوله تعالى ﴿وما نقموا منهم إلّا أن يؤمنوا بالله العزيز الحميد﴾.**\n**وأمّا علّةُ الإذن فقد استخرجها السعديُّ من الآية**، قال: «**وهذا يدلّ على حكمة الجهاد، وأنّ المقصود منه إقامةُ دين الله، وذبُّ الكفّار المؤذين للمؤمنين، البادئين لهم بالاعتداء، عن ظلمهم واعتدائهم، والتمكّنُ من عبادة الله، وإقامةِ الشرائع الظاهرة**».\n**فتأمّلْ ثلاثة قيودٍ في كلامه**: «المؤذين»، و«**البادئين لهم بالاعتداء**»، و«عن ظلمهم واعتدائهم».\n**وأمّا المعابدُ الأربعة فقد فسّرها بلا مواربة**: «**أي: لهُدّمت هذه المعابدُ الكبار، لطوائف أهل الكتاب، معابدُ اليهود والنصارى، والمساجدُ للمسلمين**».\n**ثمّ قرّر النتيجةَ صراحةً**: «**فدلّ هذا، أنّ الجهاد مشروعٌ، لأجل دفع الصائل والمؤذي، ومقصودٌ لغيره**».\n**و«مقصودٌ لغيره» عبارةٌ دقيقة**: أي أنّه **وسيلة** لا غاية؛ **يُراد لما وراءه، لا لذاته.**","the_verdict":"**فالحاصلُ أنّ الآية التي أذنت بالقتال هي نفسُها التي بيّنت أنّه لغيره لا لذاته.**\nوالدليلُ في ترتيبها: **فإنّ ما ذُكر أنّه سيُهدم لولا الدفعُ ليس المساجدَ وحدها**، بل صوامعُ وبِيَعٌ وصلواتٌ **قبلها**. **فلو كان المقصودُ من القتال إزالةَ سائر الأديان لما كان في هدم معابدها مفسدةٌ تُذكر في مقام الامتنان.**\n**وقد فسّرها السعديُّ بأنّها «معابدُ اليهود والنصارى» ولم يتأوّلها**، **وهو ممّا يجب أن يُنقل كما هو.**\n**⭐ وأمّا قولُه «مقصودٌ لغيره» فهو مفتاحُ الباب.** فإنّ الشيء إذا كان مقصودًا لغيره **فحكمُه يدور مع ذلك الغير**: يُشرع حيث يتحقّق، ويسقط حيث لا يتحقّق. **بخلاف المقصود لذاته كالصلاة، فإنّها تُطلب في كلِّ حال.**\n**وقد جعل السعديُّ ذلك الغيرَ شيئين**: **دفعُ الصائل والمؤذي**، **والتمكّنُ من عبادة الله وإقامة الشرائع**.\n**وأمّا القيدُ الأدقُّ في كلامه فهو «البادئين لهم بالاعتداء».** **فوصفُ من أُذن في قتالهم أنّهم بدؤوا.**\n**وينبغي التنبيهُ إلى حدّ ما تحتمله الآية:** فليست هذه الآيةُ وحدها بابَ أحكام الجهاد كلِّه؛ **وفي المسألة نصوصٌ أخرى وخلافٌ لأهل العلم**، ومظانُّه كتبُ الأحكام. **وإنّما مقصودُنا ها هنا ما نطقت به هذه الآيةُ وما استخرجه منها إمامٌ بلفظه.**\n**وأمّا الفائدةُ الثانيةُ فهي في قوله ﴿ولينصرنّ الله من ينصره﴾**: أنّ النصرَ موعودٌ لمن نصر دينَ الله، **لا لمن انتسب إليه.**","for_you":"**فأمّا الذي تخرج به فثلاثة:**\n**الأوّل: إذا سُئلتَ عن القتال في الإسلام فلا تُجب من الشعارات، لا لك ولا عليك.** **بل اقرأ الآيةَ التي أذنت به أوّلَ مرّة**، وانظر بمَ علّلت، **وما الذي عدّته ممّا يُصان بها.** **فالنصُّ الذي في يدك أنفعُ من عشرِ خصوماتٍ سمعتها.**\n**والثاني: تعلّمْ من «مقصودٌ لغيره» أصلًا يجري في غير هذا الباب.** فكثيرٌ من الأعمال في الشرع وسائل، **والوسيلةُ إذا نُسيت غايتُها انقلبت غايةً وفسدت.** **فانظر في عملٍ تواظب عليه: أتذكر لأيِّ شيءٍ تفعله؟** **فمن نسي علّةَ عمله أوشك أن يعمله في غير موضعه.**\n**والثالث: خذ من ﴿إلّا أن يقولوا ربّنا الله﴾ ميزانًا لنفسك حين تُؤذى.** **فإن كان الذي يُنقم منك هو استقامتُك، فذلك شرفٌ لا شكوى.** **وإن كان الذي يُنقم منك خُلقُك وسوءُ معاملتك ثمّ زعمتَ أنّك تُؤذى في دينك، فقد لبستَ ثوبَ هؤلاء وليس لك.** **والفرقُ بينهما أنّك تعرفه في نفسك ولا يعرفه الناسُ عنك.**","grade":"ma'thur","source":"قولُ السعديّ في سبب الإخراج («إلا أنهم وحدوا الله، وعبدوه مخلصين له الدين، فإن كان هذا ذنبا، فهو ذنبهم»)، واستخراجُه لحكمة الجهاد («وهذا يدل على حكمة الجهاد، وأن المقصود منه إقامة دين الله، وذب الكفار المؤذين للمؤمنين، البادئين لهم بالاعتداء، عن ظلمهم واعتدائهم، والتمكن من عبادة الله، وإقامة الشرائع الظاهرة»)، وتفسيرُه للمعابد الأربعة («أي: لهدمت هذه المعابد الكبار، لطوائف أهل الكتاب، معابد اليهود والنصارى، والمساجد للمسلمين»)، وتقريرُه («فدل هذا، أن الجهاد مشروع، لأجل دفع الصائل والمؤذي، ومقصود لغيره»): كلُّها بنصّها في تفسير السعديّ (٢٢:٤٠).","honesty":"وممّا يجب أن يُقال:\n**لم نعرض لأحكام الجهاد على وجهها**، وفيها نصوصٌ أخرى وخلافٌ مبسوطٌ لأهل العلم، **ومظانُّه كتبُ الأحكام لا هذه الوقفة**. **وإنّما نقلنا ما نطقت به هذه الآيةُ وما استخرجه السعديُّ منها بلفظه.** **ومن أخذ هذه الوقفةَ وحدها حكمًا في الباب فقد حمّلها ما لا تحتمل.**\n**وأمّا تفسيرُ «الصوامع» و«البيع» و«الصلوات» فمشهورٌ عند المفسّرين، ونقلناه بلفظ السعديّ ها هنا** («معابد اليهود والنصارى»).\n**وأمّا بيانُنا لمعنى «مقصودٌ لغيره» (أنّه وسيلةٌ يدور حكمُها مع غايتها) فشرحٌ منّا لعبارته، وهو معنًى أصوليٌّ معروف؛ ولسنا ننسب إليه أكثر من لفظه.**\n**وأمّا قولُنا إنّه يُقال كثيرًا إنّ القتال شُرع لحمل الناس على الدين، فوصفٌ لواقعٍ نراه، لا إحصاءَ عندنا به.**"}},{"n":41,"reflection":{"text":"«الذين إن مكناهم في الأرض أقاموا الصلاة وآتوا الزكاة وأمروا بالمعروف ونهوا عن المنكر ولله عاقبة الأمور»: المؤمنون الذين إن مكّنّاهم في الأرضِ ونصرناهم أقاموا الصلاةَ وآتوا الزكاةَ وأمروا بالمعروفِ ونهوا عن المنكر، ولله عاقبةُ الأمورِ كلِّها؛ ففي هذا أنّ التمكينَ الحقَّ يُثمِر إقامةَ الدينِ والإصلاح، وأنّ العاقبةَ لله ولأوليائه؛ فإذا مكّنك الله في أمرٍ فأقم الصلاةَ وآتِ الزكاةَ وأمر بالمعروفِ وانهَ عن المنكر، فذلك شكرُ التمكينِ وثمرته الصحيحة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["أقاموا الصلاة وآتوا الزكاة","ولله عاقبة الأمور"],"heart_state":{"text":"استعمالُ التمكينِ في إقامةِ الدينِ والإصلاح."},"action":{"text":"إذا مكّنك الله في أهلٍ أو عملٍ أو ولاية، فأقم الصلاةَ وآتِ الزكاةَ وأمر بالمعروفِ وانهَ عن المنكر؛ فذلك شكرُ التمكينِ وثمرته، والعاقبةُ لله ولمن أصلح، لا لمن أفسد وطغى في تمكينه."}}]},{"title":"تسليةُ النبيِّ بتكذيبِ الأمم، وعبرةُ القرى","range":[42,48],"theme":"تكذيبُ الأممِ السابقةِ لرسلهم، وعمى القلوب، واستعجالُ العذاب","verses":[{"n":42,"reflection":{"text":"«وإن يكذبوك فقد كذبت قبلهم قوم نوح وعاد وثمود»، وإن يكذّبك قومك يا محمد فقد كذّبت قبلهم قومُ نوحٍ وعادٌ وثمود؛ ففي هذا تسليةُ النبيِّ ﷺ بأنّ التكذيبَ سنّةٌ لاقاها من قبله، وأنّ عاقبةَ المكذّبين معلومة؛ فتسلَّ عند تكذيبِ الناسِ لك على الحقِّ بأنّ الرسلَ قبلك كُذِّبوا، واثبت، فالعاقبةُ للمرسلين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسلّي بسنّةِ تكذيبِ الأممِ للرسلِ والثبات."},"action":{"text":"تسلَّ عند تكذيبِ الناسِ لك حين تدعو إلى الحقّ بأنّ الرسلَ قبلك كُذِّبوا وصبروا، واثبت على دعوتك؛ فالتكذيبُ سنّةٌ ماضية، والعاقبةُ للمرسلين وأتباعهم، لا للمكذّبين."}},{"n":43,"reflection":{"text":"«وقوم إبراهيم وقوم لوط»، وكذّبت قومُ إبراهيمَ وقومُ لوطٍ رسلهم؛ ففي هذا استكمالُ ذكرِ الأممِ المكذّبةِ لأنبيائها، وأنّ التكذيبَ لاقاه أفضلُ الرسلِ كإبراهيمَ ولوط، فلا غرابةَ أن يلاقيه محمدٌ ﷺ؛ فاثبت على الحقِّ ولو كُذِّبت، فقد كُذِّب من هو خيرٌ منك، والعاقبةُ للصابرين على الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الحقِّ اقتداءً بالأنبياءِ المكذَّبين."},"action":{"text":"اثبت على الحقِّ ولو كُذِّبت وأوذيت، فقد كُذِّب إبراهيمُ ولوطٌ وسائرُ الأنبياء؛ فالتكذيبُ لا يقدح في الحقّ ولا في حامله، والعاقبةُ الحسنةُ للصابرين على الحقِّ الداعين إليه، فاقتدِ بهم."}},{"n":44,"reflection":{"text":"«وأصحاب مدين وكذب موسى فأمليت للكافرين ثم أخذتهم فكيف كان نكير»، وأصحابُ مدينَ (قومُ شعيب)، وكُذِّب موسى، فأمهلتُ الكافرين حينًا ثم أخذتهم بالعذاب، فكيف كان إنكاري عليهم وعقوبتي لهم؟ كان شديدًا؛ ففي هذا أنّ الإمهالَ لا يعني الإفلات، وأنّ أخذَ الله للظالمين شديد؛ فلا يغرّنك إمهالُ الله للمكذّبين، فإنّ أخذه أليمٌ شديد، والعاقبةُ لأهلِ الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ بالإمهال، والعلمُ بشدّةِ أخذِ الله."},"action":{"text":"لا يغرّنك إمهالُ الله للظالمين والمكذّبين، فإنما يُملي لهم ثم يأخذهم أخذًا شديدًا؛ فالحلمُ لا يعني الإهمال، فاحذر أن تكون من الظالمين، واثبت على الحقِّ واثقًا بعاقبته."}},{"n":45,"reflection":{"text":"«فكأين من قرية أهلكناها وهي ظالمة فهي خاوية على عروشها وبئر معطلة وقصر مشيد»: فكثيرٌ من القرى أهلكناها وهي ظالمةٌ بكفرها، فهي خاليةٌ ساقطةٌ سقوفها، وكم من بئرٍ عُطِّلت من أهلها، وقصرٍ مرتفعٍ مجصَّصٍ خلا من ساكنيه؛ ففي هذا عبرةٌ بآثارِ الظالمين الخاويةِ بعد عمرانها، وأنّ الظلمَ يُخرِب الديار؛ فاعتبر بآثارِ الأممِ الهالكة، واحذر الظلمَ الذي أخلى ديارهم، فالدنيا لا تبقى لظالم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بآثارِ الظالمين الخاوية، والحذرُ من الظلم."},"action":{"text":"اعتبر بآثارِ الأممِ الظالمةِ التي خوت ديارها وعُطِّلت آبارها وخلت قصورها، واحذر الظلمَ الذي أهلكها؛ فالدنيا لا تبقى لأحدٍ ولا سيّما الظالم، فالزم العدلَ يبقَ لك أثرٌ حسن."}},{"n":46,"reflection":{"text":"«أفلم يسيروا في الأرض فتكون لهم قلوب يعقلون بها أو آذان يسمعون بها فإنها لا تعمى الأبصار ولكن تعمى القلوب التي في الصدور»: أفلم يسيروا في الأرضِ فيروا آثارَ الهالكين فتعقل قلوبهم وتسمع آذانهم فيعتبروا؟ فليست العبرةُ بعمى البصر، بل العمى الحقيقيُّ عمى القلوبِ عن إدراكِ الحقّ؛ ففي هذا أنّ الاعتبارَ بالقلبِ لا بمجردِ النظر، وأنّ أخطرَ العمى عمى القلب؛ فاطلب بصيرةَ القلبِ لتعتبر وتبصر الحقّ، فعمى القلبِ أشدُّ من عمى العين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["تعمى القلوب التي في الصدور"],"heart_state":{"text":"طلبُ بصيرةِ القلبِ والحذرُ من عماه."},"action":{"text":"اطلب بصيرةَ القلبِ التي بها تعقل وتعتبر وتبصر الحقّ، واحذر عمى القلبِ فهو أشدُّ من عمى البصر؛ فسِر في الأرضِ ناظرًا بقلبك لا بعينك فقط، معتبرًا بآثارِ من مضى، فالعبرةُ للقلوبِ الواعية."}},{"n":47,"reflection":{"text":"«ويستعجلونك بالعذاب ولن يخلف الله وعده وإن يوما عند ربك كألف سنة مما تعدون»، ويستعجلك المكذّبون بالعذابِ استهزاءً، ولن يخلف الله وعده بوقوعه، وإنّ يومًا عند ربّك في العذابِ أو في طولِ الأمدِ كألفِ سنةٍ ممّا تعدّون؛ ففي هذا أنّ وعدَ الله بالعذابِ واقعٌ لا يتخلّف، وأنّ حسابَ الزمنِ عند الله غيرُ حسابنا؛ فلا تستعجل أمرَ الله، واعلم أنّ وعده حقٌّ آتٍ في وقته، والأناةُ من صفاتِ الله في تدبيره.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ استعجالِ أمرِ الله، واليقينُ بتحقّقِ وعده."},"action":{"text":"لا تستعجل وعدَ الله ولا وعيدَه، فوعده حقٌّ آتٍ لا يتخلّف وإن تأخّر، والزمنُ عنده غيرُ زمنك؛ فالزم اليقينَ والصبرَ والاستعداد، ولا تستبطئ ما وعد به، فكلُّ آتٍ قريبٌ في حسابِ الله."}},{"n":48,"reflection":{"text":"«وكأين من قرية أمليت لها وهي ظالمة ثم أخذتها وإلي المصير»، وكثيرٌ من القرى أمهلتُها وهي ظالمةٌ ثم أخذتها بالعذاب، وإليّ المرجعُ والمصيرُ للجزاء؛ ففي هذا تكرارُ التذكيرِ بأنّ الإمهالَ يعقبه الأخذ، وأنّ المصيرَ إلى الله؛ فلا يغرّنك إمهالُ الله للظالمين، واعمل لمصيرك إليه، فالكلُّ راجعٌ إليه فيُجزى بعمله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["وإلي المصير"],"heart_state":{"text":"العلمُ بأنّ الإمهالَ يعقبه الأخذُ والمصيرُ إلى الله."},"action":{"text":"لا يغرّنك إمهالُ الله للظالمين، فإنّ الأخذَ يعقب الإمهال، والمصيرَ إليه للحساب؛ فاعمل لمرجعك إلى الله، وحاسب نفسك قبل أن تُحاسَب، فكلُّ أحدٍ راجعٌ إليه فيُجزى بما عمل."}}]},{"title":"النذارةُ وجزاءُ الفريقين","range":[49,51],"theme":"أنّ الرسولَ نذير، ومغفرةُ المؤمنين، وعقوبةُ المعاندين","verses":[{"n":49,"reflection":{"text":"«قل يا أيها الناس إنما أنا لكم نذير مبين»: قل يا محمد: يا أيها الناسُ إنما أنا لكم منذرٌ مبيّنٌ للحقِّ محذّرٌ من العذاب؛ ففي هذا بيانُ وظيفةِ النبيِّ ﷺ بالإنذارِ والبلاغ، وأنّ الهدايةَ بيدِ الله؛ فاتّعظ بالنذارةِ التي بلّغها الرسول، ولا تنتظر أن يُكرَه أحدٌ على الهدى، فوظيفةُ الرسولِ البلاغُ، والانتفاعُ باختيارك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بنذارةِ الرسولِ والمبادرةُ للاستجابة."},"action":{"text":"اتّعظ بنذارةِ الرسولِ ﷺ وتحذيره، وبادر بالاستجابةِ لدعوته قبل فواتِ الأوان؛ فوظيفتُه البلاغُ والإنذار، والاهتداءُ باختيارك وسعيك؛ فلا تكن ممّن يُنذَر فلا يتّعظ، بل سارع إلى الهدى."}},{"n":50,"reflection":{"text":"«فالذين آمنوا وعملوا الصالحات لهم مغفرة ورزق كريم»: فالذين آمنوا وعملوا الصالحاتِ لهم مغفرةٌ لذنوبهم ورزقٌ كريمٌ حسنٌ في الجنّة؛ ففي هذا بشارةُ أهلِ الإيمانِ والعملِ بالمغفرةِ والرزقِ الكريم، وأنّ الجزاءَ فضلٌ من الله؛ فاجمع بين الإيمانِ والعملِ الصالح، لتنال المغفرةَ والرزقَ الكريم، فذلك جزاءُ من صدق مع الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين الإيمانِ والعملِ لنيلِ المغفرةِ والرزقِ الكريم."},"action":{"text":"اجمع بين الإيمانِ الصادقِ والعملِ الصالح، لتنال مغفرةَ الله لذنوبك ورزقه الكريمَ في جنّته؛ فذلك جزاءُ أهلِ الإيمانِ والعمل، فاجتهد أن تكون منهم، وارجُ فضلَ الله ومغفرته."}},{"n":51,"reflection":{"text":"«والذين سعوا في آياتنا معاجزين أولئك أصحاب الجحيم»، والذين اجتهدوا في إبطالِ آياتنا وصدِّ الناسِ عنها ظانّين أنهم يعجزوننا ويفوتوننا، أولئك أصحابُ النارِ الملازمون لها؛ ففي هذا أنّ السعيَ في إبطالِ الحقِّ ومعاندتِه موجبٌ للنار، وأنّ المعاندَ لن يعجز الله؛ فاحذر السعيَ في معارضةِ الحقِّ وصدِّ الناسِ عنه، فعاقبتُه الجحيم، والزم نصرةَ الحقِّ لا معاداته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من السعيِ في إبطالِ الحقِّ ومعاندته."},"action":{"text":"احذر أن تسعى في معارضةِ آياتِ الله وصدِّ الناسِ عنها أو تزهيدهم فيها، فعاقبةُ ذلك النار؛ ولن يعجز أحدٌ اللهَ ولن يفوته؛ فالزم نصرةَ الحقِّ والدعوةَ إليه، لا السعيَ في إبطاله ومعاداته."}}]},{"title":"إحكامُ الله لآياته، وإخباتُ أهلِ العلم","range":[52,55],"theme":"أنّ الله ينسخ ما يلقيه الشيطانُ ويحكم آياته، وفتنةُ مرضى القلوب","verses":[{"n":52,"reflection":{"text":"«وما أرسلنا من قبلك من رسول ولا نبي إلا إذا تمنى ألقى الشيطان في أمنيته فينسخ الله ما يلقي الشيطان ثم يحكم الله آياته والله عليم حكيم»، وما أرسلنا قبلك رسولًا ولا نبيًّا إلا إذا تلا الوحيَ أو تمنّى هدايةَ قومه، سعى الشيطانُ في إلقاءِ الشبهاتِ والتشويشِ على دعوته، فيبطل الله ما يلقيه الشيطان ويحكم آياته ويثبّتها، والله عليمٌ حكيم؛ ففي هذا أنّ الشيطانَ يسعى للتشويشِ على الحقّ، وأنّ الله يحفظ آياته ويحكمها؛ فاعلم أنّ الله يحفظ دينه من كيدِ الشيطان، فاثبت على الحقّ، ولا يزعزعك ما يُلقيه المبطلون من شبهات.","source":"تفسير السعدي","grade":"ma'thur"},"names":["يحكم الله آياته","عليم حكيم"],"heart_state":{"text":"الثقةُ بأنّ الله يحفظ آياته ويبطل كيدَ الشيطان."},"action":{"text":"اثبت على الحقِّ واثقًا بأنّ الله يحفظ دينه وآياته ويبطل ما يلقيه الشيطانُ من الشبهاتِ والتشويش؛ فلا تزعزعك شبهاتُ المبطلين، فإنّ الله عليمٌ حكيمٌ يحكم آياته ويثبّتها، وينصر الحقّ."}},{"n":53,"reflection":{"text":"«ليجعل ما يلقي الشيطان فتنة للذين في قلوبهم مرض والقاسية قلوبهم وإن الظالمين لفي شقاق بعيد»: ليجعل الله ما يلقيه الشيطانُ من الشبهاتِ اختبارًا للذين في قلوبهم شكٌّ ونفاق، والقاسيةِ قلوبهم عن الحقّ، وإنّ الظالمين لفي عداوةٍ وخلافٍ بعيدٍ عن الحقّ؛ ففي هذا أنّ الشبهاتِ فتنةٌ تكشف مرضَ القلوبِ وقسوتها، وأنّ سلامةَ القلبِ تعصم منها؛ فاحرص على سلامةِ قلبك ولينه للحقّ، لتنجوَ من فتنةِ الشبهات، فالقلبُ المريضُ والقاسي يفتنه ما يعصم منه القلبُ السليم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على سلامةِ القلبِ ولينه للحقّ."},"action":{"text":"احرص على سلامةِ قلبك من الشكِّ والنفاقِ ومن القسوة، وليّنه للحقِّ بذكرِ الله والعمل؛ فالشبهاتُ فتنةٌ تكشف مرضَ القلوبِ وقسوتها، والقلبُ السليمُ اللينُ للحقِّ يعصمه الله منها، فاعتنِ بقلبك."}},{"n":54,"reflection":{"text":"«وليعلم الذين أوتوا العلم أنه الحق من ربك فيؤمنوا به فتخبت له قلوبهم وإن الله لهاد الذين آمنوا إلى صراط مستقيم»، وليعلم الراسخون في العلمِ أنّ القرآنَ هو الحقُّ من ربّك فيزدادوا إيمانًا به، وتخضع وتطمئنّ له قلوبهم، وإنّ الله لهادي المؤمنين إلى صراطٍ مستقيم؛ ففي هذا أنّ أهلَ العلمِ يزدادون بالفتنِ يقينًا، وأنّ الإخباتَ ثمرةُ العلمِ الصحيح، وأنّ الله يهدي المؤمنين؛ فاطلب العلمَ النافعَ ليثبت يقينك عند الشبهات، وليخبت قلبك للحقّ، فالعلمُ يعصم من الفتنةِ ويورث الإخبات.","source":"تفسير السعدي","grade":"ma'thur"},"names":["أنه الحق من ربك","فتخبت له قلوبهم"],"heart_state":{"text":"طلبُ العلمِ النافعِ ليورث اليقينَ والإخبات."},"action":{"text":"اطلب العلمَ النافعَ بآياتِ الله ومعانيها، فبه يثبت يقينك عند الشبهاتِ ويخبت قلبك للحقِّ ويطمئنّ؛ فالراسخون في العلمِ تزيدهم الفتنُ إيمانًا، والله يهدي المؤمنين إلى الصراطِ المستقيم، فالعلمُ عصمة."}},{"n":55,"reflection":{"text":"«ولا يزال الذين كفروا في مرية منه حتى تأتيهم الساعة بغتة أو يأتيهم عذاب يوم عقيم»، ولا يزال الكفارُ في شكٍّ من القرآنِ حتى تأتيهم الساعةُ فجأةً أو يأتيهم عذابُ يومٍ عقيمٍ لا خيرَ فيه لهم؛ ففي هذا أنّ الشكَّ يلازم الكافرَ حتى يفاجئه الموتُ أو العذاب، وأنّ الغفلةَ عن الحقِّ تدوم حتى البغتة؛ فاخرج من الشكِّ إلى اليقينِ ما دمت في مهلة، ولا تؤخّر الإيمانَ حتى تفاجئك الساعةُ أو العذاب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الخروجُ من الشكِّ إلى اليقينِ قبل البغتة."},"action":{"text":"اخرج من الشكِّ والريبِ إلى اليقينِ والإيمانِ ما دمت في مهلةِ الحياة، ولا تؤخّر ذلك حتى تفاجئك الساعةُ بغتةً أو يأتيك العذاب؛ فالكافرُ يبقى في شكِّه حتى الفجأة، فبادر باليقينِ والعملِ قبل الفوات."}}]},{"title":"الملكُ يومَ القيامةِ لله، وجزاءُ المهاجرين","range":[56,60],"theme":"حكمُ الله بين الخلق، ورزقُ المهاجرين الشهداء، ونصرُ المظلوم","verses":[{"n":56,"reflection":{"text":"«الملك يومئذ لله يحكم بينهم فالذين آمنوا وعملوا الصالحات في جنات النعيم»: الملكُ يوم القيامةِ لله وحده يحكم بين الخلق، فالذين آمنوا وعملوا الصالحاتِ في جناتِ النعيمِ الدائم؛ ففي هذا انفرادُ الله بالملكِ والحكمِ يوم القيامة، وبشارةُ المؤمنين بالنعيم؛ فاستحضر أنّ الملكَ يومئذٍ لله وحده يحكم بالعدل، فاعمل بالإيمانِ والصالحاتِ لتكون من أهلِ جناتِ النعيم.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الملك يومئذ لله"],"heart_state":{"text":"استحضارُ انفرادِ الله بالملكِ والحكم، والعملُ للنعيم."},"action":{"text":"استحضر أنّ الملكَ يوم القيامةِ لله وحده يحكم بين الخلقِ بالعدل، فاعمل بالإيمانِ والعملِ الصالحِ لتكون من أهلِ جناتِ النعيم؛ فمن أيقن بذلك الحكمِ العدلِ استعدَّ له بالطاعةِ وترْكِ ما يسخط الله."}},{"n":57,"reflection":{"text":"«والذين كفروا وكذبوا بآياتنا فأولئك لهم عذاب مهين»، والذين كفروا وكذّبوا بآياتنا فأولئك لهم عذابٌ مذلٌّ مهينٌ يوم القيامة؛ ففي هذا أنّ الكفرَ والتكذيبَ عاقبتهما العذابُ المهين، مقابلَ نعيمِ المؤمنين؛ فاحذر الكفرَ والتكذيبَ بآياتِ الله، فعاقبتهما الذلُّ والهوان، والزم الإيمانَ والتصديقَ لتنجوَ من العذابِ المهين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكفرِ والتكذيبِ خشيةَ العذابِ المهين."},"action":{"text":"احذر الكفرَ والتكذيبَ بشيءٍ من آياتِ الله، فعاقبتهما عذابٌ مهينٌ مذلّ؛ والزم الإيمانَ بكلِّ ما جاء عن الله وتصديقه، لتكون من أهلِ النعيمِ لا من أهلِ العذابِ المهين، فبينهما بونٌ عظيم."}},{"n":58,"reflection":{"text":"«والذين هاجروا في سبيل الله ثم قتلوا أو ماتوا ليرزقنهم الله رزقا حسنا وإن الله لهو خير الرازقين»، والذين تركوا ديارهم في سبيلِ الله ثم قُتِلوا في الجهادِ أو ماتوا، ليرزقنّهم الله رزقًا حسنًا في الجنّة، وإنّ الله لهو خيرُ الرازقين؛ ففي هذا فضلُ الهجرةِ في سبيلِ الله، وأنّ المهاجرَ يُرزَق أحسنَ الرزقِ حيًّا وميّتًا؛ فاهجر ما نهى الله عنه، واسعَ في سبيله، واثقًا بأنّ الله خيرُ الرازقين يعوّض من ترك لأجله.","source":"تفسير السعدي","grade":"ma'thur"},"names":["خير الرازقين"],"heart_state":{"text":"فضلُ الهجرةِ في سبيلِ الله، والثقةُ برزقه الحسن."},"action":{"text":"اهجر ما نهاك الله عنه، واسعَ في سبيله ببذلِ نفسك ومالك، واثقًا بأنّ الله يرزق المهاجرين في سبيله رزقًا حسنًا حيّهم وميّتهم؛ فهو خيرُ الرازقين، يعوّض من ترك شيئًا لأجله خيرًا منه."}},{"n":59,"reflection":{"text":"«ليدخلنهم مدخلا يرضونه وإن الله لعليم حليم»: ليدخلنّ الله المهاجرين مدخلًا (الجنّةَ) يرضونه ويسرّهم، وإنّ الله لعليمٌ بأحوالهم ونيّاتهم، حليمٌ لا يعجل بالعقوبة؛ ففي هذا وعدُ الله للمهاجرين بمدخلٍ يرضونه، وإثباتُ علمه وحلمه؛ فاعمل لله واثقًا بأنه يدخلك مدخلًا ترضاه، وأنه عليمٌ بنيّتك، حليمٌ يمهل ويرحم، فأخلص له عملك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["عليم حليم"],"heart_state":{"text":"العملُ لله رجاءَ مدخلٍ يُرضي، والثقةُ بعلمه وحلمه."},"action":{"text":"اعمل لله بإخلاصٍ واثقًا بأنه يدخلك مدخلًا ترضاه في جنّته، وأنه عليمٌ بنيّتك وسعيك، حليمٌ يمهلك ويرحمك؛ فاطمئن إلى علمه وحلمه، وأخلص عملك له رجاءَ رضاه ومدخله الكريم."}},{"n":60,"reflection":{"text":"«ذلك ومن عاقب بمثل ما عوقب به ثم بغي عليه لينصرنه الله إن الله لعفو غفور»: ذلك الأمرُ، ومن انتصر لنفسه بمثلِ ما ظُلِم به دون تجاوز، ثم بُغِي عليه ثانيةً، لينصرنّه الله، إنّ الله لعفوٌّ غفورٌ يحبّ العفو؛ ففي هذا جوازُ الانتصارِ بالعدلِ من الظالم، ووعدُ الله بنصرِ المظلوم، والحضُّ على العفوِ مع القدرة؛ فانتصر لحقّك بالعدلِ إن اضطُررت، وثق بنصرِ الله للمظلوم، والعفوُ أفضلُ فالله عفوٌّ غفورٌ يحبّ العافين.","source":"تفسير السعدي","grade":"ma'thur"},"names":["لينصرنه الله","عفو غفور"],"heart_state":{"text":"الانتصارُ بالعدل، والثقةُ بنصرِ الله للمظلوم، وفضلُ العفو."},"action":{"text":"إن ظُلِمت فلك أن تنتصر بمثلِ ما ظُلِمت به بلا تجاوز، وثق بأنّ الله ينصر المظلوم؛ والعفوُ مع القدرةِ أفضلُ وأقربُ إلى الله، فهو عفوٌّ غفورٌ يحبّ العفو؛ فوازِن بين حقّك في الانتصارِ وفضلِ العفو."}}]},{"title":"آياتُ قدرةِ الله وأسماؤه الحسنى","range":[61,64],"theme":"إيلاجُ الليلِ والنهار، وأنّ الله هو الحقّ، وإحياءُ الأرضِ، وغناه","verses":[{"n":61,"reflection":{"text":"«ذلك بأن الله يولج الليل في النهار ويولج النهار في الليل وأن الله سميع بصير»: ذلك النصرُ والقدرةُ بأنّ الله يدخل الليلَ في النهارِ فيطول ويقصر، ويدخل النهارَ في الليلِ كذلك، وأنّ الله سميعٌ لأقوالكم بصيرٌ بأعمالكم؛ ففي هذا أنّ من قدر على تصريفِ الليلِ والنهارِ قادرٌ على نصرِ أوليائه، وأنّ الله سميعٌ بصير؛ فتأمّل قدرةَ الله في تعاقبِ الليلِ والنهار، واعلم أنه سميعٌ بصيرٌ لا يخفى عليه شيء، فراقبه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["سميع بصير"],"heart_state":{"text":"تأمّلُ قدرةِ الله في الليلِ والنهار، ومراقبتُه."},"action":{"text":"تأمّل قدرةَ الله في إيلاجِ الليلِ في النهارِ والنهارِ في الليل، فمن قدر على ذلك قادرٌ على نصرك وكفايتك؛ وراقبه فهو سميعٌ لأقوالك بصيرٌ بأعمالك، لا يخفى عليه شيءٌ من أمرك سرًّا أو علنًا."}},{"n":62,"reflection":{"text":"«ذلك بأن الله هو الحق وأن ما يدعون من دونه هو الباطل وأن الله هو العلي الكبير»: ذلك بأنّ الله هو الحقُّ الثابتُ في ذاته وصفاته وأفعاله، وأنّ ما يدعون من دونه من الآلهةِ هو الباطلُ الزائل، وأنّ الله هو العليُّ فوق خلقه، الكبيرُ في ذاته وصفاته؛ ففي هذا تقريرُ أنّ الله هو الحقُّ وما سواه باطل، وإثباتُ علوّه وكبريائه؛ فاعبد الحقَّ وحده، وابرأ من كلِّ باطلٍ يُدعى من دونه، وعظّم الله العليَّ الكبير.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الله هو الحق","العلي الكبير"],"heart_state":{"text":"عبادةُ الحقِّ وحده، وتعظيمُ الله العليِّ الكبير."},"action":{"text":"اعبد الله الذي هو الحقُّ وحده، وابرأ من كلِّ معبودٍ باطلٍ سواه، وعظّم الله العليَّ فوق خلقه، الكبيرَ في ذاته وصفاته؛ فمن عرف أنّ الله هو الحقُّ وما سواه باطلٌ أخلص له العبادةَ والتعظيم."}},{"n":63,"reflection":{"text":"«ألم تر أن الله أنزل من السماء ماء فتصبح الأرض مخضرة إن الله لطيف خبير»: ألم تشاهد أنّ الله أنزل من السماءِ مطرًا فتصبح الأرضُ خضراءَ بالنبات؟ إنّ الله لطيفٌ بعباده خبيرٌ بمصالحهم؛ ففي هذا آيةٌ من آياتِ قدرةِ الله ولطفه، وأنّ إحياءَ الأرضِ دليلٌ على البعثِ ولطفِ الله؛ فتأمّل لطفَ الله في إنزالِ الماءِ وإخضرارِ الأرض، واعلم أنه لطيفٌ خبيرٌ يدبّر أمرك بلطفٍ وعلم، فثق به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["لطيف خبير"],"heart_state":{"text":"تأمّلُ لطفِ الله في آياته، والثقةُ بتدبيره."},"action":{"text":"تأمّل لطفَ الله في إنزالِ الماءِ من السماءِ فتخضرّ الأرض، وثق بأنه لطيفٌ خبيرٌ يدبّر أمورك بلطفٍ وعلمٍ لا يخفى عليه مصلحتك؛ فمن عرف لطفَ الله وخبرته اطمأنّ إلى تدبيره ورضي بقضائه."}},{"n":64,"reflection":{"text":"«له ما في السماوات وما في الأرض وإن الله لهو الغني الحميد»: له وحده ملكُ ما في السماواتِ والأرض، وإنّ الله لهو الغنيُّ عن خلقه، الحميدُ في ذاته وأفعاله المستحقُّ للحمد؛ ففي هذا إثباتُ ملكِ الله الشاملِ وغناه وحمده؛ فاعلم أنّ كلَّ شيءٍ ملكٌ لله، وأنه غنيٌّ عنك وأنت الفقيرُ إليه، حميدٌ يستحقُّ حمدك؛ فاحمده على نعمه، والزم بابه فأنت الفقيرُ وهو الغنيّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الغني الحميد"],"heart_state":{"text":"استشعارُ غنى الله وحمده، والافتقارُ إليه."},"action":{"text":"استشعر أنّ كلَّ شيءٍ ملكٌ لله، وأنه الغنيُّ عنك وأنت الفقيرُ المحتاجُ إليه، الحميدُ المستحقُّ لكلِّ حمد؛ فاحمده على نعمه، والزم بابه بالافتقارِ والدعاء، فمن عرف غناه وفقرَ نفسه لزم عبوديّته."}}]},{"title":"تسخيرُ الكونِ ورأفةُ الله","range":[65,66],"theme":"تسخيرُ ما في الأرضِ والفلكِ وإمساكُ السماء، وإحياءُ الله وإماتتُه","verses":[{"n":65,"reflection":{"text":"«ألم تر أن الله سخر لكم ما في الأرض والفلك تجري في البحر بأمره ويمسك السماء أن تقع على الأرض إلا بإذنه إن الله بالناس لرءوف رحيم»: ألم تعلم أنّ الله سخّر لكم ما في الأرضِ من الدوابِّ والثمار، والسفنَ تجري في البحرِ بأمره لمنافعكم، ويمسك السماءَ أن تسقط على الأرضِ إلا بإذنه؟ إنّ الله بالناسِ لرؤوفٌ رحيمٌ بهذا التسخيرِ والإمساك؛ ففي هذا تعدادُ نعمِ الله ورأفتِه، وأنّ التسخيرَ والحفظَ من رحمته؛ فاشكر الله على تسخيرِ الكونِ لك وحفظِه إياك، واستشعر رأفتَه ورحمته بك في كلِّ نعمة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["بالناس لرءوف رحيم"],"heart_state":{"text":"شكرُ تسخيرِ الكونِ واستشعارُ رأفةِ الله ورحمته."},"action":{"text":"اشكر الله على تسخيرِ ما في الأرضِ لك، والفلكِ في البحر، وإمساكِه السماءَ أن تقع؛ واستشعر رأفتَه ورحمته بك في كلِّ نعمةٍ وحفظ؛ فمن تأمّل نعمَ الله ورأفته أحبّه وشكره وأخلص له العبادة."}},{"n":66,"reflection":{"text":"«وهو الذي أحياكم ثم يميتكم ثم يحييكم إن الإنسان لكفور»، وهو الذي أحياكم بعد العدم، ثم يميتكم عند انتهاءِ آجالكم، ثم يحييكم للبعث، إنّ الإنسانَ لكثيرُ الكفرِ لنعمِ الله وجحودٌ لها؛ ففي هذا إثباتُ الإحياءِ والإماتةِ والبعثِ بيدِ الله، وذمُّ كفرِ الإنسانِ للنعم؛ فاشكر الله الذي أحياك ويميتك ويحييك، ولا تكن من الكفورِ الجاحدِ لنعمه، بل اذكرها واحمده عليها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["أحياكم ثم يميتكم ثم يحييكم"],"heart_state":{"text":"شكرُ نعمةِ الحياةِ ونبذُ كفرانِ النعم."},"action":{"text":"اشكر الله الذي أحياك من عدمٍ ويميتك ثم يحييك للبعث، واذكر نعمه ولا تجحدها؛ فالإنسانُ مجبولٌ على كفرانِ النعمةِ إلا من رحم الله، فجاهد نفسك على الشكرِ الدائم، واحذر أن تكون من الكفور."}}]},{"title":"ثباتُ النبيِّ على الحقّ، وعلمُ الله الشامل","range":[67,72],"theme":"الدعوةُ إلى الله بلا منازعة، وحكمُ الله بين المختلفين، وعجزُ المعبوداتِ الباطلة","verses":[{"n":67,"reflection":{"text":"«لكل أمة جعلنا منسكا هم ناسكوه فلا ينازعنك في الأمر وادع إلى ربك إنك لعلى هدى مستقيم»: لكلِّ أمّةٍ جعلنا شريعةً وعبادةً يعملون بها، فلا ينازعنّك المشركون في أمرِ دينك، وادعُ إلى ربّك، إنك على هدًى مستقيمٍ لا اعوجاجَ فيه؛ ففي هذا الأمرُ بالثباتِ على الحقِّ وعدمِ الالتفاتِ لمنازعةِ المبطلين، والدعوةِ إلى الله؛ فاثبت على هداك، ولا تدع منازعةَ المبطلين تشغلك، وامضِ في الدعوةِ إلى ربّك واثقًا بأنك على الحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":["إنك لعلى هدى مستقيم"],"heart_state":{"text":"الثباتُ على الهدى، والمضيُّ في الدعوةِ بلا التفاتٍ للمنازعة."},"action":{"text":"اثبت على الحقِّ الذي أنت عليه، ولا تدع منازعةَ المبطلين ومجادلتهم تشغلك أو تزعزعك، وامضِ في الدعوةِ إلى ربّك واثقًا بأنك على هدًى مستقيم؛ فالثباتُ على الحقِّ والدعوةُ إليه خيرٌ من الانشغالِ بالجدال."}},{"n":68,"reflection":{"text":"«وإن جادلوك فقل الله أعلم بما تعملون»، وإن جادلوك بعد وضوحِ الحقِّ عنادًا، فقل: الله أعلمُ بأعمالكم وسيجازيكم عليها؛ ففي هذا تفويضُ أمرِ المعاندِ إلى الله بعد إقامةِ الحجّة، وأنّ الجدالَ العقيمَ يُقطَع بالتفويض؛ فإذا أعياك جدالُ المعاندِ فوّض أمره إلى الله، ولا تُطِل المراءَ العقيم، فالله أعلمُ بهم وسيجازيهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تفويضُ أمرِ المعاندِ إلى الله وقطعُ الجدالِ العقيم."},"action":{"text":"إذا جادلك معاندٌ بعد وضوحِ الحقِّ فوّض أمره إلى الله «الله أعلم بما تعملون»، ولا تُطِل المراءَ العقيمَ الذي لا يُثمِر؛ فقد أدّيت البلاغ، والله أعلمُ بهم وأحكمُ فيهم، فاصرف وقتك لما ينفع."}},{"n":69,"reflection":{"text":"«الله يحكم بينكم يوم القيامة فيما كنتم فيه تختلفون»: الله يحكم بينكم أيها المختلفون يوم القيامةِ فيما كنتم تختلفون فيه من الحقِّ والباطل، فيتبيّن المحقُّ من المبطل؛ ففي هذا أنّ فصلَ الاختلافِ إلى الله يوم القيامة، وأنّ الحقَّ سيتبيّن؛ فالزم الحقَّ ودع الخصومة، واعلم أنّ الله سيحكم بينك وبين مخالفك بالعدل، فاحرص أن تكون على الحقِّ يومئذ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ الحقِّ والعلمُ بأنّ الله يفصل في الاختلاف."},"action":{"text":"الزم الحقَّ في كلِّ ما تختلف فيه، ودع الخصومةَ والمراء، واعلم أنّ الله يحكم بين المختلفين يوم القيامةِ بالعدلِ فيتبيّن المحقّ؛ فاحرص أن تكون على الحقِّ الذي يرضاه الله يوم يفصل بين عباده."}},{"n":70,"reflection":{"text":"«ألم تعلم أن الله يعلم ما في السماء والأرض إن ذلك في كتاب إن ذلك على الله يسير»: ألم تعلم أنّ الله يعلم كلَّ ما في السماءِ والأرض، وأنّ ذلك مكتوبٌ في اللوحِ المحفوظ، وأنّ ذلك على الله يسيرٌ سهل؟ ففي هذا إثباتُ سعةِ علمِ الله وإحاطتِه، وأنّ إحصاءَ كلِّ شيءٍ عليه يسير؛ فاستحضر أنّ الله يعلم كلَّ شيءٍ وأحصاه في كتاب، فراقبه في سرّك وعلنك، فلا يخفى عليه من أمرك شيء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["يعلم ما في السماء والأرض"],"heart_state":{"text":"استحضارُ سعةِ علمِ الله ومراقبتُه."},"action":{"text":"استحضر أنّ الله يعلم كلَّ ما في السماءِ والأرضِ وأحصاه في كتاب، وأنّ ذلك عليه يسير؛ فراقبه في سرّك وعلانيتك، واعلم أنّ عملك كلَّه محصًى محفوظ، فاستحيِ أن يجدك حيث نهاك."}},{"n":71,"reflection":{"text":"«ويعبدون من دون الله ما لم ينزل به سلطانا وما ليس لهم به علم وما للظالمين من نصير»، ويعبد المشركون من دون الله ما لم ينزل به حجّةً ولا برهانًا، ولا عندهم به علم، بل تقليدٌ وهوى، وما للظالمين من ناصرٍ ينصرهم من عذابِ الله؛ ففي هذا أنّ الشركَ لا مستندَ له من علمٍ ولا برهان، وأنّ الظالمَ لا ناصرَ له؛ فلا تعبد إلا بدليلٍ وعلم، واحذر الشركَ الذي لا برهانَ عليه، فالظالمُ المشركُ لا نصيرَ له عند الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عبادةُ الله بعلمٍ وبرهان، ونبذُ الشركِ الذي لا دليلَ عليه."},"action":{"text":"لا تعبد ولا تعتقد إلا بعلمٍ وبرهانٍ من الوحي، واحذر الشركَ والبدعَ التي لا مستندَ لها إلا التقليدَ والهوى؛ فعبادةُ ما لا دليلَ عليه ظلمٌ لا نصيرَ لصاحبه، فالزم ما دلّ عليه العلمُ والبرهان."}},{"n":72,"reflection":{"text":"«وإذا تتلى عليهم آياتنا بينات تعرف في وجوه الذين كفروا المنكر يكادون يسطون بالذين يتلون عليهم آياتنا قل أفأنبئكم بشر من ذلكم النار وعدها الله الذين كفروا وبئس المصير»، وإذا تُقرأ على الكفارِ آياتنا الواضحاتِ ترى في وجوههم الكراهيةَ والإنكار، يكادون يبطشون بالذين يتلونها عليهم من شدّةِ غيظهم، قل لهم: أفأخبركم بما هو شرٌّ من هذا الغيظ؟ إنها النارُ وعدها الله الكافرين، وبئس المصير؛ ففي هذا شدّةُ عداوةِ الكفارِ للحقّ حتى يكادون يبطشون بأهله، وأنّ مآلهم النار؛ فاثبت على تلاوةِ الحقِّ ودعوته ولو أغاظ المبطلين، واحذر أن تكون ممّن يغيظه الحقُّ فمصيره النار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الحقِّ ولو أغاظ المبطلين، والحذرُ من عداوته."},"action":{"text":"اثبت على تلاوةِ الحقِّ والدعوةِ إليه ولو أغاظ المبطلين وأظهروا الكراهية، فذلك دأبهم مع أهلِ الحقّ؛ واحذر أن تكون ممّن يغيظه الحقُّ ويكرهه، فإنّ مصيرَ الكافرين النارُ وبئس المصير، فأحبَّ الحقَّ وانصره."}}]},{"title":"مثلُ عجزِ الآلهة، وخاتمةُ الأمرِ بالجهاد","range":[73,78],"theme":"ضعفُ المعبوداتِ عن خلقِ ذبابة، واصطفاءُ الرسل، والأمرُ بالعبادةِ والجهاد","verses":[{"n":73,"reflection":{"text":"«يا أيها الناس ضرب مثل فاستمعوا له إن الذين تدعون من دون الله لن يخلقوا ذبابا ولو اجتمعوا له وإن يسلبهم الذباب شيئا لا يستنقذوه منه ضعف الطالب والمطلوب»: يا أيها الناسُ ضُرِب مثلٌ فاستمعوا له بتدبّر: إنّ الذين تعبدون من دون الله لن يقدروا على خلقِ ذبابةٍ واحدةٍ ولو اجتمعوا كلُّهم لذلك، وإن سلبهم الذبابُ شيئًا لم يقدروا على استرداده منه، ضعُف العابدُ (الطالب) والمعبودُ (المطلوب)؛ ففي هذا حجّةٌ دامغةٌ على عجزِ المعبوداتِ الباطلةِ وحقارتها، وأنّ من عبدها ضعيفٌ مثلها؛ فلا تعبد عاجزًا لا يخلق ذبابةً ولا يدفعها، وأخلص العبادةَ للخالقِ القادرِ وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":["لن يخلقوا ذبابا ولو اجتمعوا له"],"heart_state":{"text":"إفرادُ الله بالعبادةِ لعجزِ كلِّ ما سواه."},"action":{"text":"لا تعبد ولا ترجُ إلا الله الخالقَ القادر، فكلُّ ما يُعبَد من دونه عاجزٌ لا يخلق ذبابةً ولا يستنقذ منها ما سلبته؛ فتدبّر هذا المثلَ لتعرف حقارةَ الشركِ وعجزَ معبوداته، وأخلص عبادتك لله وحده."}},{"n":74,"reflection":{"text":"«ما قدروا الله حق قدره إن الله لقوي عزيز»: ما عظّم المشركون الله حقَّ تعظيمه حيث عبدوا معه العاجزين، إنّ الله لقويٌّ عزيزٌ لا يغالَب؛ ففي هذا أنّ الشركَ تنقّصٌ لقدرِ الله، وأنّ من عرف قوّةَ الله وعزّته وحّده؛ فعظّم الله حقَّ تعظيمه بإفرادِه بالعبادةِ وتنزيهِه، واعرف قوّته وعزّته، فمن قدر الله حقَّ قدره لم يشرك به شيئًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["قوي عزيز"],"heart_state":{"text":"تعظيمُ الله حقَّ تعظيمه بتوحيدِه ومعرفةِ قوّته."},"action":{"text":"عظّم الله حقَّ تعظيمه بإفرادِه بالعبادةِ وتنزيهِه عن الشريكِ والنقص، واعرف قوّته وعزّته التي لا تُغالَب؛ فمن قدر الله حقَّ قدره لم يعدل به عاجزًا، ولم يشرك به شيئًا، وأخلص له دينه."}},{"n":75,"reflection":{"text":"«الله يصطفي من الملائكة رسلا ومن الناس إن الله سميع بصير»: الله يختار من الملائكةِ رسلًا (كجبريل) ومن الناسِ رسلًا (كالأنبياء)، إنّ الله سميعٌ لأقوالِ عباده بصيرٌ بمن يستحقُّ الاصطفاء؛ ففي هذا أنّ الاصطفاءَ للرسالةِ بيدِ الله وحكمته، وأنه سميعٌ بصيرٌ يعلم من يصلح لها؛ فسلّم لاختيارِ الله لرسله، واعلم أنه أعلمُ بمن يصطفي، فلا اعتراضَ على حكمته، وهو السميعُ البصير.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الله يصطفي من الملائكة رسلا","سميع بصير"],"heart_state":{"text":"التسليمُ لاصطفاءِ الله، والعلمُ بأنه أعلمُ بعباده."},"action":{"text":"سلّم لاختيارِ الله واصطفائه لرسله من الملائكةِ والناس، فهو أعلمُ بمن يصلح لحملِ رسالته؛ وهو سميعٌ بصيرٌ لا يخفى عليه شيء؛ فلا تعترض على حكمته في اختياره، وأقبل على ما جاء به رسله بالتسليم."}},{"n":76,"reflection":{"text":"«يعلم ما بين أيديهم وما خلفهم وإلى الله ترجع الأمور»: يعلم الله ما بين أيدي رسلِه وما خلفهم من الأحوالِ كلِّها، وإلى الله وحده ترجع الأمورُ كلُّها فيقضي فيها؛ ففي هذا إثباتُ إحاطةِ علمِ الله، وأنّ مرجعَ الأمورِ إليه؛ فاعلم أنّ الله محيطٌ بكلِّ أمرك، وأنّ الأمورَ كلَّها ترجع إليه، فسلّم أمرك إليه، واعمل لمرجعك الذي إليه ترجع الأمور.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["إلى الله ترجع الأمور"],"heart_state":{"text":"التسليمُ لله المحيطِ علمُه، والعملُ لمرجعِ الأمور."},"action":{"text":"اعلم أنّ الله محيطٌ علمًا بكلِّ ما بين يديك وما خلفك، وأنّ الأمورَ كلَّها ترجع إليه فيقضي فيها؛ فسلّم أمرك إليه وتوكّل عليه، واعمل صالحًا لمرجعك، فكلُّ شيءٍ صائرٌ إلى الله وحكمه."}},{"n":77,"reflection":{"text":"«يا أيها الذين آمنوا اركعوا واسجدوا واعبدوا ربكم وافعلوا الخير لعلكم تفلحون»: يا أيها المؤمنون اركعوا واسجدوا في صلاتكم، واعبدوا ربّكم بأنواعِ العبادة، وافعلوا الخيرَ من كلِّ برٍّ ومعروف، رجاءَ أن تفلحوا وتفوزوا؛ ففي هذا الأمرُ بالصلاةِ والعبادةِ وفعلِ الخير، وأنّ الفلاحَ ثمرتها؛ فأقم الصلاةَ بركوعها وسجودها، واعبد ربّك، وافعل الخيراتِ كلَّها، فبها الفلاحُ في الدنيا والآخرة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["اركعوا واسجدوا واعبدوا ربكم","لعلكم تفلحون"],"heart_state":{"text":"لزومُ الصلاةِ والعبادةِ وفعلِ الخيرِ طلبًا للفلاح."},"action":{"text":"أقم الصلاةَ بخشوعِ ركوعها وسجودها، واعبد ربّك بأنواعِ العبادة، وافعل الخيرَ من كلِّ برٍّ ومعروفٍ ونفعٍ للخلق؛ فبهذه الثلاثِ يُرجى الفلاحُ والفوزُ في الدنيا والآخرة، فاجعلها ديدنك ودأبك."}},{"n":78,"reflection":{"text":"«وجاهدوا في الله حق جهاده هو اجتباكم وما جعل عليكم في الدين من حرج ملة أبيكم إبراهيم هو سماكم المسلمين من قبل وفي هذا ليكون الرسول شهيدا عليكم وتكونوا شهداء على الناس فأقيموا الصلاة وآتوا الزكاة واعتصموا بالله هو مولاكم فنعم المولى ونعم النصير»، وجاهدوا في سبيلِ الله حقَّ الجهادِ بأنفسكم وأموالكم وألسنتكم ومجاهدةِ النفس، هو اختاركم لدينه، وما جعل عليكم في الدينِ من ضيقٍ ومشقّةٍ فوق الطاقة، دينكم ملّةُ أبيكم إبراهيم، هو سمّاكم المسلمين من قبلُ في الكتبِ السابقةِ وفي القرآن، ليكون الرسولُ شاهدًا عليكم بالبلاغِ وتكونوا شهداءَ على الناسِ به، فأقيموا الصلاةَ وآتوا الزكاةَ واعتصموا بالله، هو مولاكم، فنِعم المولى ونِعم النصير؛ ففي هذا خاتمةٌ جامعة: الأمرُ بالجهادِ الحقّ، والامتنانُ بيُسرِ الدين، وشرفُ اسمِ المسلمين، والأمرُ بالصلاةِ والزكاةِ والاعتصامِ بالله؛ فجاهد في الله حقَّ جهاده، واعتصم به فهو نِعم المولى ونِعم النصير.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["جاهدوا في الله حق جهاده","هو مولاكم فنعم المولى ونعم النصير"],"heart_state":{"text":"الجهادُ في الله حقَّ جهاده، والاعتصامُ به وحده."},"action":{"text":"جاهد في سبيلِ الله حقَّ الجهادِ: جاهد نفسك وهواك والشيطان، وابذل في نصرةِ دينه؛ واشكر يُسرَ الدينِ الذي لا حرجَ فيه، واعتزَّ باسمِ الإسلام، وأقم الصلاةَ وآتِ الزكاة، واعتصم بالله وحده، فهو نِعم المولى ونِعم النصير."}}]}],"coverage":{"covered":78,"total":78}};
